window.QBANK = window.QBANK || {};
window.QBANK["smp-pjok"] = {
  level: "SMP", subject: "PJOK", duration: 900,
  questions: [
    { q: "Start jongkok digunakan untuk nomor lari ....", options: ["Jarak jauh", "Jarak menengah", "Jarak pendek", "Maraton"], answer: 2, solution: "1. Start jongkok memberi dorongan tolakan kaki yang kuat saat awal lari. 2. Dorongan kuat hanya berguna pada lari yang mengutamakan kecepatan penuh sejak start. 3. Lari yang mengutamakan kecepatan penuh sejak awal adalah lari jarak pendek." },
    { q: "Pada aba-aba 'Siap' dalam start jongkok, posisi badan pelari adalah ....", options: ["Duduk rileks di lintasan", "Pinggul diangkat lebih tinggi dari bahu", "Berdiri tegak menghadap garis finis", "Badan telentang di lintasan"], answer: 1, solution: "1. Aba-aba 'Siap' adalah persiapan sesaat sebelum berlari. 2. Pada posisi ini lutut kaki belakang diangkat sehingga pinggul naik. 3. Pinggul yang lebih tinggi dari bahu memberi sudut tolakan terbaik untuk melesat ke depan." },
    { q: "Lari jarak menengah dan jarak jauh menggunakan start ....", options: ["Jongkok", "Berdiri", "Meluncur", "Duduk"], answer: 1, solution: "1. Lari jarak menengah dan jauh menempuh jarak 800 meter ke atas. 2. Pelari tidak butuh ledakan kecepatan di awal, melainkan irama langkah yang hemat tenaga. 3. Karena itu dipakai start berdiri yang sederhana dan tidak menguras tenaga." },
    { q: "Teknik memasuki garis finis yang benar pada lari jarak pendek adalah ....", options: ["Melompat setinggi mungkin", "Berhenti mendadak tepat di garis", "Membusungkan dada ke depan", "Menengok ke belakang"], answer: 2, solution: "1. Yang dinilai adalah bagian dada yang pertama menyentuh garis finis. 2. Melompat atau berhenti mendadak justru memperlambat laju badan. 3. Membusungkan dada ke depan membuat dada mencapai garis lebih cepat tanpa mengurangi kecepatan." },
    { q: "Urutan aba-aba dalam start jongkok adalah ....", options: ["Siap - Bersedia - Ya", "Bersedia - Siap - Ya", "Ya - Siap - Bersedia", "Mulai - Siap - Bersedia"], answer: 1, solution: "1. Start jongkok selalu diawali aba-aba 'Bersedia' untuk mengambil posisi di balok start. 2. Dilanjutkan 'Siap' untuk mengangkat pinggul. 3. Terakhir bunyi pistol atau 'Ya' sebagai tanda berlari." },
    { q: "Tahapan lompat jauh yang benar secara berurutan adalah ....", options: ["Tolakan - awalan - melayang - mendarat", "Awalan - tolakan - melayang - mendarat", "Melayang - awalan - tolakan - mendarat", "Awalan - melayang - tolakan - mendarat"], answer: 1, solution: "1. Lompat jauh dimulai dengan lari awalan untuk mendapat kecepatan. 2. Kecepatan itu diubah menjadi lompatan saat tolakan dengan satu kaki. 3. Setelah itu pelompat melayang di udara lalu mendarat dengan dua kaki." },
    { q: "Seorang pelompat jauh dinyatakan gagal (diskualifikasi) apabila ....", options: ["Mendarat dengan dua kaki", "Kakinya melewati papan tolakan", "Melakukan awalan kurang dari 20 meter", "Jatuh ke belakang saat mendarat"], answer: 1, solution: "1. Tolakan harus dilakukan tepat pada papan tolakan. 2. Kaki yang melewati ujung papan berarti pelompat mencuri jarak awalan. 3. Karena itu lompatan dinyatakan gagal." },
    { q: "Pada lompat jauh, tolakan dilakukan dengan .... dan pendaratan dengan ....", options: ["Dua kaki - satu kaki", "Satu kaki - dua kaki", "Satu kaki - satu kaki", "Dua kaki - dua kaki"], answer: 1, solution: "1. Tolakan memakai satu kaki terkuat agar lompatan maksimal. 2. Bertolak dengan dua kaki akan menghentikan laju lari awalan. 3. Mendarat dengan dua kaki menjaga keseimbangan dan mencegah cedera." },
    { q: "Tolak peluru disebut 'menolak' dan bukan 'melempar' karena ....", options: ["Peluru dilempar ke atas sejauh mungkin", "Peluru didorong dengan satu tangan dari dekat bahu", "Peluru dilempar dengan dua tangan", "Peluru diayunkan seperti lembing"], answer: 1, solution: "1. Dalam tolak peluru, peluru menempel di leher atau bahu lalu didorong ke depan-atas. 2. Gerakan ini adalah dorongan (tolakan), bukan ayunan lengan seperti melempar. 3. Peluru juga tidak boleh terlepas dari bahu sebelum ditolak." },
    { q: "Sudut tolakan peluru yang menghasilkan tolakan terjauh adalah sekitar ....", options: ["15 derajat", "42 derajat", "75 derajat", "90 derajat"], answer: 1, solution: "1. Sudut terlalu kecil membuat peluru cepat jatuh ke tanah. 2. Sudut terlalu besar membuat peluru melambung tapi tidak jauh. 3. Sudut sekitar 42 derajat memberi perpaduan terbaik antara ketinggian dan jarak mendatar." },
    { q: "Nomor lari yang termasuk lari jarak pendek adalah ....", options: ["800 meter", "1500 meter", "100 meter", "5000 meter"], answer: 2, solution: "1. Lari jarak pendek mengandalkan kecepatan penuh sepanjang lintasan. 2. Nomornya adalah 100 meter, 200 meter, dan 400 meter. 3. 800 meter ke atas sudah termasuk jarak menengah dan jauh." },
    { q: "Nomor lari 5000 meter dan 10.000 meter termasuk lari jarak ....", options: ["Pendek", "Menengah", "Jauh", "Estafet"], answer: 2, solution: "1. Lari jarak jauh menempuh jarak di atas 3000 meter. 2. Nomor 5000 meter dan 10.000 meter membutuhkan daya tahan, bukan kecepatan sesaat. 3. Jadi keduanya termasuk lari jarak jauh." },
    { q: "Dalam lari estafet 4 x 100 meter, tongkat estafet harus diberikan ....", options: ["Di sembarang tempat di lintasan", "Di dalam zona pergantian tongkat", "Setelah garis finis", "Sebelum garis start"], answer: 1, solution: "1. Setiap tim estafet punya zona pergantian tongkat sepanjang 20 meter. 2. Pemberian tongkat di luar zona membuat tim didiskualifikasi. 3. Aturan ini menjaga pergantian berlangsung adil dan aman." },
    { q: "Jumlah pemain sepak bola dalam satu tim di lapangan adalah ....", options: ["7 orang", "9 orang", "11 orang", "13 orang"], answer: 2, solution: "1. Peraturan FIFA menetapkan sepak bola dimainkan 11 lawan 11. 2. Terdiri dari 1 penjaga gawang dan 10 pemain lapangan. 3. Jumlah kurang dari 11 hanya pada permainan modifikasi, bukan aturan resmi." },
    { q: "Lama pertandingan sepak bola resmi adalah ....", options: ["2 x 30 menit", "2 x 40 menit", "2 x 45 menit", "4 x 15 menit"], answer: 2, solution: "1. Aturan resmi FIFA menetapkan pertandingan berlangsung dua babak. 2. Setiap babak berdurasi 45 menit dengan jeda istirahat di antaranya. 3. Jadi total waktu normal adalah 2 x 45 menit." },
    { q: "Tendangan penalti dalam sepak bola dilakukan dari jarak ....", options: ["6 meter dari gawang", "9 meter dari gawang", "11 meter dari gawang", "16 meter dari gawang"], answer: 2, solution: "1. Titik penalti sudah ditandai di dalam kotak penalti. 2. Jaraknya ditetapkan 11 meter dari garis gawang. 3. Tendangan ini diberikan saat terjadi pelanggaran di dalam kotak penalti." },
    { q: "Apabila bola keluar melalui garis sisi lapangan, permainan dilanjutkan dengan ....", options: ["Tendangan sudut", "Tendangan gawang", "Lemparan ke dalam", "Tendangan bebas"], answer: 2, solution: "1. Garis sisi adalah batas samping lapangan. 2. Bola yang keluar lewat sisi diberikan kepada tim lawan dari pemain yang terakhir menyentuh. 3. Cara melanjutkannya adalah lemparan ke dalam (throw-in) dengan kedua tangan dari belakang kepala." },
    { q: "Teknik menyundul bola dalam sepak bola disebut ....", options: ["Shooting", "Dribbling", "Heading", "Tackling"], answer: 2, solution: "1. Menyundul bola menggunakan dahi untuk mengarahkan bola. 2. Istilah bahasa Inggris untuk sundulan kepala adalah heading. 3. Shooting adalah menendang ke gawang, dribbling menggiring bola, tackling merebut bola." },
    { q: "Pemain yang menerima kartu merah dalam sepak bola harus ....", options: ["Keluar lapangan dan timnya bermain dengan 10 orang", "Istirahat 5 menit lalu masuk lagi", "Membayar denda lalu lanjut bermain", "Pindah menjadi penjaga gawang"], answer: 0, solution: "1. Kartu merah adalah hukuman untuk pelanggaran berat. 2. Pemain yang terkena harus meninggalkan lapangan. 3. Timnya tidak boleh memasukkan pemain pengganti sehingga bermain dengan 10 orang." },
    { q: "Seorang pemain dinyatakan offside apabila ....", options: ["Berdiri di daerah pertahanan sendiri", "Menerima bola dari lemparan ke dalam", "Berada lebih dekat ke gawang lawan daripada pemain bertahan terakhir saat bola diumpan", "Berlari lebih cepat dari pemain lawan"], answer: 2, solution: "1. Offside menilai posisi pemain saat bola diumpankan rekannya. 2. Pemain offside jika berada di depan pemain bertahan terakhir lawan di daerah lawan. 3. Aturan ini mencegah pemain menunggu di dekat gawang lawan." },
    { q: "Jumlah pemain bola voli dalam satu tim di lapangan adalah ....", options: ["4 orang", "5 orang", "6 orang", "7 orang"], answer: 2, solution: "1. Peraturan resmi bola voli menetapkan 6 pemain tiap tim di lapangan. 2. Terdiri dari pemain depan dan pemain belakang dengan tugas masing-masing. 3. Formasi 6 orang memungkinkan rotasi posisi setiap perpindahan servis." },
    { q: "Tinggi net bola voli untuk pertandingan putra adalah ....", options: ["2,24 meter", "2,35 meter", "2,43 meter", "2,55 meter"], answer: 2, solution: "1. Tinggi net putra dan putri dibedakan karena perbedaan jangkauan. 2. Net putra ditetapkan 2,43 meter dari lantai. 3. Net putri lebih rendah yaitu 2,24 meter." },
    { q: "Dalam satu rally, sebuah tim bola voli maksimal menyentuh bola sebanyak ....", options: ["1 kali", "2 kali", "3 kali", "4 kali"], answer: 2, solution: "1. Aturan memberi kesempatan tiap tim menyusun serangan. 2. Batasnya adalah tiga kali sentuhan sebelum bola harus dikembalikan. 3. Sentuhan keempat dianggap pelanggaran." },
    { q: "Smash dalam bola voli adalah ....", options: ["Pukulan pertama untuk memulai permainan", "Pukulan keras menukik dari atas net ke daerah lawan", "Pukulan melambung untuk menerima servis", "Tangkapan bola dengan dua tangan"], answer: 1, solution: "1. Smash dilakukan pelompat di dekat net saat bola umpan melambung tinggi. 2. Bola dipukul keras dengan telapak tangan mengarah menukik ke lapangan lawan. 3. Pukulan pertama untuk memulai permainan disebut servis, bukan smash." },
    { q: "Servis dalam bola voli harus dilakukan ....", options: ["Dari dalam lapangan", "Dari belakang garis akhir lapangan", "Sambil melompat melewati net", "Dari samping tiang net"], answer: 1, solution: "1. Servis adalah pukulan pembuka tiap rally. 2. Aturan mewajibkan server berdiri di belakang garis akhir lapangan. 3. Menginjak atau melewati garis saat servis membuat servis tidak sah." },
    { q: "Jumlah pemain bola basket dalam satu tim di lapangan adalah ....", options: ["3 orang", "5 orang", "6 orang", "11 orang"], answer: 1, solution: "1. Peraturan FIBA menetapkan basket dimainkan 5 lawan 5. 2. Kelima posisi itu adalah point guard, shooting guard, small forward, power forward, dan center. 3. Jumlah 11 adalah sepak bola dan 6 adalah bola voli." },
    { q: "Lay up dalam bola basket adalah teknik ....", options: ["Menembak dari garis tiga angka", "Menembak sambil melayang dekat ring setelah dua langkah", "Mengoper bola memantul ke lantai", "Menahan bola dengan dua tangan"], answer: 1, solution: "1. Lay up diawali dengan dribble mendekati ring. 2. Pemain mengambil dua langkah lalu melompat dan memasukkan bola ke ring. 3. Teknik ini punya peluang masuk paling besar karena jaraknya sangat dekat." },
    { q: "Pelanggaran travelling dalam bola basket terjadi ketika pemain ....", options: ["Menggiring bola terlalu cepat", "Melangkah lebih dari dua langkah sambil memegang bola tanpa dribble", "Menembak bola keluar lapangan", "Menyentuh bola dengan kaki"], answer: 1, solution: "1. Saat memegang bola, pemain hanya boleh berhenti (pivot) atau mendribble. 2. Berjalan atau berlari lebih dari dua langkah tanpa memantulkan bola disebut travelling. 3. Pelanggarannya membuat bola berpindah ke tim lawan." },
    { q: "Tembakan yang dilakukan dari dalam garis tiga angka bernilai ....", options: ["1 poin", "2 poin", "3 poin", "4 poin"], answer: 1, solution: "1. Nilai tembakan bergantung pada posisi saat menembak. 2. Tembakan dari dalam garis busur tiga angka bernilai 2 poin. 3. Nilai 3 poin hanya untuk tembakan dari luar garis, dan 1 poin untuk lemparan bebas." },
    { q: "Saat melakukan servis bulu tangkis, kok harus dipukul ....", options: ["Setinggi kepala", "Di bawah pinggang", "Setinggi net", "Dari atas kepala"], answer: 1, solution: "1. Aturan servis bulu tangkis membatasi ketinggian pukulan. 2. Kok harus dipukul saat berada di bawah pinggang server. 3. Servis dari atas seperti smash dinyatakan fault." },
    { q: "Tinggi net bulu tangkis dari lantai lapangan adalah ....", options: ["1,24 meter", "1,40 meter", "1,55 meter", "1,80 meter"], answer: 2, solution: "1. Net bulu tangkis dipasang di tengah lapangan. 2. Tingginya ditetapkan 1,55 meter dari lantai. 3. Ukuran ini berlaku untuk nomor tunggal maupun ganda." },
    { q: "Dropshot dalam bulu tangkis adalah pukulan ....", options: ["Keras dan menukik tajam", "Halus dan jatuh tipis di dekat net lawan", "Melambung tinggi ke belakang lapangan", "Mendatar cepat setinggi net"], answer: 1, solution: "1. Dropshot bertujuan mengecoh lawan yang menunggu di belakang. 2. Kok dipukul halus agar jatuh tepat di dekat net daerah lawan. 3. Pukulan keras menukik disebut smash, sedangkan pukulan mendatar disebut drive." },
    { q: "Dalam tenis meja, servis dinyatakan sah apabila bola ....", options: ["Langsung melewati net tanpa memantul", "Memantul sekali di meja sendiri lalu melewati net", "Dilempar ke arah lawan tanpa dipukul", "Dipukul sekeras mungkin ke badan lawan"], answer: 1, solution: "1. Aturan servis tenis meja mewajibkan bola menyentuh meja penyervis dulu. 2. Setelah memantul di sisi sendiri, bola melewati net ke sisi lawan. 3. Servis yang langsung melewati net tanpa memantul dinyatakan tidak sah." },
    { q: "Satu set permainan tenis meja dimenangkan dengan mencapai ....", options: ["11 poin dengan selisih 2 poin", "15 poin tanpa selisih", "21 poin dengan selisih 1 poin", "25 poin dengan selisih 2 poin"], answer: 0, solution: "1. Aturan modern tenis meja memakai sistem 11 poin per set. 2. Pemenang harus unggul minimal 2 poin atas lawan. 3. Jika 10-10, permainan dilanjutkan sampai selisih 2 poin tercapai." },
    { q: "Pegangan bet seperti memegang pena dalam tenis meja disebut ....", options: ["Shakehand grip", "Penhold grip", "American grip", "Seemiller grip"], answer: 1, solution: "1. Ada dua pegangan dasar bet tenis meja. 2. Pegangan seperti berjabat tangan disebut shakehand grip. 3. Pegangan seperti memegang pena disebut penhold grip." },
    { q: "Ukuran meja tenis meja yang sesuai standar adalah ....", options: ["2,00 m x 1,00 m", "2,74 m x 1,525 m", "3,00 m x 1,50 m", "2,50 m x 1,25 m"], answer: 1, solution: "1. Federasi tenis meja dunia menetapkan ukuran meja standar. 2. Panjang meja 2,74 meter dan lebar 1,525 meter. 3. Tinggi meja dari lantai adalah 76 cm." },
    { q: "Pada gerakan roll depan, dagu harus ....", options: ["Menengadah ke atas", "Ditempelkan ke dada", "Digoyangkan ke kanan-kiri", "Dibiarkan bebas"], answer: 1, solution: "1. Roll depan adalah gerakan mengguling ke depan di atas matras. 2. Dagu ditempelkan ke dada agar kepala menekuk dan tengkuk yang menyentuh matras. 3. Jika dagu menengadah, dahi bisa terbentur matras dan berbahaya." },
    { q: "Sikap lilin dalam senam lantai bertumpu pada ....", options: ["Kedua telapak tangan", "Kepala dan leher", "Kedua siku dan punggung atas", "Lutut dan kaki"], answer: 2, solution: "1. Sikap lilin adalah posisi kaki lurus ke atas menyerupai lilin. 2. Tumpuan badan berada pada kedua siku yang menopang pinggang serta punggung atas atau bahu. 3. Bertumpu pada kepala sangat berbahaya bagi tulang leher." },
    { q: "Gerakan handstand adalah sikap ....", options: ["Berdiri dengan kepala di bawah", "Berdiri dengan kedua tangan dan kaki lurus ke atas", "Tidur telentang dengan kaki ditekuk", "Duduk dengan kaki diluruskan"], answer: 1, solution: "1. Handstand berarti berdiri dengan tangan sebagai tumpuan. 2. Kedua tangan lurus menopang badan sementara kaki lurus ke atas. 3. Gerakan ini melatih kekuatan lengan, bahu, dan keseimbangan." },
    { q: "Gerakan kayang dalam senam lantai bertujuan melatih ....", options: ["Kekuatan kaki", "Kelenturan punggung dan kekuatan lengan", "Daya tahan jantung", "Kecepatan lari"], answer: 1, solution: "1. Kayang adalah posisi badan melengkung seperti busur. 2. Tumpuannya adalah kedua tangan dan kedua kaki dengan perut menghadap ke atas. 3. Posisi ini meregangkan otot punggung sekaligus melatih kekuatan lengan dan bahu." },
    { q: "Berikut ini yang termasuk alat dalam senam irama adalah ....", options: ["Palang tunggal dan kuda-kuda", "Simpai, bola, pita, tali, dan gada", "Matras dan balok titian", "Gelang-gelang dan palang sejajar"], answer: 1, solution: "1. Senam irama adalah senam yang gerakannya mengikuti irama musik. 2. Alat yang dipakai bersifat ringan dan dimainkan mengikuti irama. 3. Alat resminya adalah simpai, bola, pita, tali, dan gada." },
    { q: "Gerakan guling ke belakang (back roll) diawali dari posisi ....", options: ["Berdiri tegak menghadap matras", "Jongkok membelakangi matras", "Telentang di atas matras", "Berlutut menghadap matras"], answer: 1, solution: "1. Guling ke belakang adalah putaran badan ke arah belakang. 2. Gerakan diawali dari jongkok dengan punggung menghadap matras. 3. Tangan diletakkan di samping telinga untuk menolak saat badan berguling." },
    { q: "Latihan push-up bertujuan untuk mengukur dan melatih ....", options: ["Kelenturan pinggang", "Kekuatan otot lengan dan bahu", "Daya tahan jantung-paru", "Keseimbangan tubuh"], answer: 1, solution: "1. Push-up adalah gerakan menaik-turunkan badan dengan tumpuan tangan. 2. Beban badan ditahan oleh otot lengan, dada, dan bahu. 3. Karena itu push-up mengukur komponen kebugaran berupa kekuatan otot." },
    { q: "Tes sit and reach digunakan untuk mengukur komponen kebugaran ....", options: ["Kecepatan", "Kelenturan", "Kelincahan", "Daya tahan otot"], answer: 1, solution: "1. Sit and reach dilakukan dengan duduk dan meraih ujung kaki sejauh mungkin. 2. Jarak raihan menunjukkan kemampuan sendi dan otot untuk diregangkan. 3. Kemampuan meregang inilah yang disebut kelenturan." },
    { q: "Tes lari 12 menit (tes Cooper) bertujuan mengukur ....", options: ["Kecepatan reaksi", "Daya tahan jantung dan paru-paru", "Kekuatan otot perut", "Kelenturan sendi"], answer: 1, solution: "1. Tes Cooper meminta pelari menempuh jarak sejauh mungkin dalam 12 menit. 2. Semakin jauh jarak tempuh, semakin baik kemampuan jantung-paru memasok oksigen. 3. Jadi tes ini mengukur daya tahan kardiovaskular, bukan kecepatan sesaat." },
    { q: "Rumus sederhana untuk memperkirakan denyut nadi maksimal adalah ....", options: ["220 dikurangi umur", "100 ditambah umur", "220 dikali umur", "60 dibagi umur"], answer: 0, solution: "1. Denyut nadi maksimal menurun seiring bertambahnya umur. 2. Rumus praktis yang umum dipakai adalah 220 dikurangi umur dalam tahun. 3. Contohnya anak umur 14 tahun memiliki denyut nadi maksimal sekitar 206 kali per menit." },
    { q: "Tujuan utama melakukan pemanasan sebelum berolahraga adalah ....", options: ["Agar cepat lelah", "Menyiapkan otot dan mencegah cedera", "Menambah berat badan", "Mengurangi nafsu makan"], answer: 1, solution: "1. Pemanasan berupa gerakan ringan yang menaikkan suhu tubuh perlahan. 2. Otot yang hangat menjadi lebih lentur dan siap menerima beban berat. 3. Karena itu risiko cedera seperti kram dan keseleo dapat ditekan." },
    { q: "Pertolongan pertama pada luka lecet ringan yang benar adalah ....", options: ["Menutup luka tanpa dibersihkan", "Membersihkan dengan air mengalir lalu tutup dengan kasa steril", "Mengoleskan pasta gigi pada luka", "Membiarkan luka terkena debu agar cepat kering"], answer: 1, solution: "1. Luka lecet berisiko kemasukan kuman dan kotoran. 2. Membersihkan dengan air mengalir menghilangkan kotoran penyebab infeksi. 3. Setelah bersih, luka ditutup kasa steril agar tetap bersih; pasta gigi justru mengiritasi luka." },
    { q: "Penanganan yang tepat saat mengalami keseleo pada pergelangan kaki adalah ....", options: ["Dipijat keras agar bengkak hilang", "Digerak-gerakkan paksa supaya lentur lagi", "Diistirahatkan, dikompres es, dibebat, dan ditinggikan", "Direndam air panas lalu dipakai berlari"], answer: 2, solution: "1. Keseleo adalah cedera pada ligamen akibat gerakan berlebihan. 2. Prinsip RICE: Rest (istirahat), Ice (kompres es), Compression (bebat), Elevation (tinggikan). 3. Memijat atau menggerakkan paksa justru memperparah robekan ligamen." },
    { q: "Saat mimisan, tindakan yang benar adalah ....", options: ["Mendongakkan kepala ke belakang", "Duduk tegak, sedikit menunduk, dan menekan hidung selama 10 menit", "Berbaring lalu menutup hidung dengan kapas basah", "Memasukkan tisu jauh ke dalam hidung"], answer: 1, solution: "1. Mendongak membuat darah mengalir ke tenggorokan dan bisa tertelan. 2. Posisi duduk tegak dengan kepala sedikit menunduk menjaga darah keluar lewat hidung. 3. Menekan cuping hidung sekitar 10 menit membantu pembuluh darah menutup." },
{ q: "Perbedaan utama jalan cepat dengan lari adalah ....", options: ["Posisi start yang berbeda", "Kecepatan langkah yang lebih lambat", "Salah satu kaki selalu menyentuh tanah", "Jarak tempuh yang lebih pendek"], answer: 2, solution: "1. Pada lari terdapat fase melayang ketika kedua kaki terangkat dari tanah. 2. Aturan jalan cepat mewajibkan salah satu kaki selalu kontak dengan tanah. 3. Pejalan yang terlihat melayang akan didiskualifikasi oleh wasit." },
    { q: "Pada jalan cepat, lutut kaki yang menapak tanah harus dalam keadaan ....", options: ["Diangkat tinggi", "Disilangkan", "Ditekuk sedikit", "Lurus"], answer: 3, solution: "1. Aturan jalan cepat menuntut kaki tumpu lurus sejak menyentuh tanah. 2. Lutut yang ditekuk membuat gerakan tampak seperti berlari kecil. 3. Kaki harus tetap lurus hingga melewati posisi tegak badan." },
    { q: "Nomor lari gawang putra adalah 110 meter, sedangkan nomor lari gawang putri adalah ....", options: ["100 meter", "200 meter", "400 meter", "80 meter"], answer: 0, solution: "1. Lari gawang adalah lari cepat sambil melompati rintangan gawang. 2. Jarak gawang putra lebih jauh karena perbedaan jangkauan langkah. 3. Nomor resminya adalah 110 meter putra dan 100 meter putri." },
    { q: "Teknik melewati gawang (hurdle) yang benar adalah ....", options: ["Melompat dengan kedua kaki rapat bersamaan", "Kaki depan diayun lurus ke depan dan kaki belakang ditekuk menyamping", "Berhenti sejenak tepat di depan gawang", "Menabrak gawang hingga roboh"], answer: 1, solution: "1. Gawang harus dilewati tanpa mengurangi kecepatan lari. 2. Kaki depan diayun lurus ke depan untuk mendarat cepat. 3. Kaki belakang ditekuk menyamping agar tidak menyangkut gawang." },
    { q: "Nomor lari 1500 meter termasuk lari jarak ....", options: ["Estafet", "Pendek", "Menengah", "Jauh"], answer: 2, solution: "1. Lari jarak menengah meliputi nomor 800 meter dan 1500 meter. 2. Nomor ini memadukan kecepatan dan daya tahan. 3. Lari jarak jauh dimulai dari 3000 meter ke atas." },
    { q: "Nomor lari 800 meter termasuk lari jarak ....", options: ["Jauh", "Maraton", "Pendek", "Menengah"], answer: 3, solution: "1. Lari jarak pendek hanya sampai 400 meter. 2. Nomor 800 meter membutuhkan kecepatan sekaligus daya tahan. 3. Karena itu 800 meter digolongkan lari jarak menengah." },
    { q: "Satu putaran penuh lintasan atletik standar sama dengan jarak ....", options: ["200 meter", "400 meter", "800 meter", "100 meter"], answer: 1, solution: "1. Lintasan atletik standar berbentuk oval. 2. Keliling lintasan jalur terdalam ditetapkan 400 meter. 3. Karena itu nomor 400 meter sama dengan satu putaran penuh." },
    { q: "Selain 4 x 100 meter, nomor lari estafet resmi lainnya adalah ....", options: ["4 x 200 meter", "4 x 400 meter", "4 x 800 meter", "4 x 1500 meter"], answer: 1, solution: "1. Lari estafet resmi dilombakan dalam dua nomor. 2. Nomor pertama adalah 4 x 100 meter yang mengandalkan kecepatan. 3. Nomor kedua adalah 4 x 400 meter yang memadukan kecepatan dan daya tahan." },
    { q: "Pada lari estafet, pelari kedua, ketiga, dan keempat menggunakan start ....", options: ["Melayang", "Jongkok", "Berdiri", "Meluncur"], answer: 0, solution: "1. Pelari pertama memakai start jongkok karena berlari dari keadaan diam. 2. Pelari berikutnya menerima tongkat sambil sudah berlari kecil. 3. Start yang diawali dengan berlari disebut start melayang." },
    { q: "Jarak resmi lari maraton adalah ....", options: ["42,915 km", "45 km", "40,195 km", "42,195 km"], answer: 3, solution: "1. Maraton adalah nomor lari jalan raya paling bergengsi. 2. Jaraknya ditetapkan berdasarkan rute Olimpiade London 1908. 3. Jarak resmi maraton adalah 42,195 kilometer." },
    { q: "Gaya lompat jauh di mana kedua kaki ditekuk ke depan seperti duduk saat melayang disebut gaya ....", options: ["Menggantung", "Berjalan di udara", "Melenting", "Jongkok"], answer: 3, solution: "1. Saat melayang pelompat dapat memakai tiga gaya. 2. Gaya jongkok dilakukan dengan menekuk kedua lutut ke depan seperti posisi duduk. 3. Gaya ini paling mudah dipelajari pemula." },
    { q: "Gaya menggantung (hang style) pada lompat jauh ditandai dengan ....", options: ["Kedua kaki diluruskan ke depan", "Kedua lengan diayun ke atas dan badan melengkung ke belakang", "Kedua kaki dikayuh seperti berjalan", "Badan meringkuk seperti bola"], answer: 1, solution: "1. Gaya menggantung bertujuan menjaga keseimbangan di udara. 2. Kedua lengan diayun ke atas dan ke belakang. 3. Badan melengkung seperti posisi menggantung sebelum mendarat." },
    { q: "Gaya berjalan di udara (hitch kick) pada lompat jauh dilakukan dengan cara ....", options: ["Memutar badan satu putaran penuh", "Mengayunkan kedua kaki seperti sedang berjalan di udara", "Menekuk kedua lutut rapat ke dada", "Meluruskan badan kaku seperti papan"], answer: 1, solution: "1. Gaya ini dipakai pelompat berpengalaman untuk menambah jarak. 2. Kedua kaki dikayuhkan di udara seperti gerakan berjalan atau berlari. 3. Kayuhan itu menjaga momentum tubuh ke depan lebih lama." },
    { q: "Pada lompat tinggi gaya flop, posisi badan saat melewati mistar adalah ....", options: ["Menyamping sejajar mistar", "Dada menempel mistar", "Perut menghadap mistar", "Punggung menghadap mistar"], answer: 3, solution: "1. Gaya flop dipopulerkan Dick Fosbury pada Olimpiade 1968. 2. Pelompat melentingkan badan hingga punggung menghadap mistar. 3. Pendaratan dilakukan dengan punggung di atas matras." },
    { q: "Ciri utama gaya straddle pada lompat tinggi adalah ....", options: ["Badan berguling dengan perut menghadap mistar", "Tolakan dengan dua kaki bersamaan", "Mendarat dengan posisi duduk", "Punggung menghadap mistar saat melayang"], answer: 0, solution: "1. Gaya straddle adalah gaya klasik sebelum gaya flop. 2. Badan berguling melewati mistar dengan perut menghadap ke bawah. 3. Kaki ayun memimpin gerakan melewati mistar." },
    { q: "Lempar lembing diawali dengan ....", options: ["Berdiri diam di dalam lingkaran", "Lari awalan lalu lembing dilempar dari atas bahu dengan satu tangan", "Memutar badan tiga kali di tempat", "Melompat sebelum melempar"], answer: 1, solution: "1. Lembing membutuhkan kecepatan awal agar meluncur jauh. 2. Pelempar melakukan lari awalan beberapa langkah. 3. Lembing kemudian dilempar dengan satu tangan dari atas bahu." },
    { q: "Berat lembing untuk nomor putra adalah ....", options: ["1000 gram", "600 gram", "700 gram", "800 gram"], answer: 3, solution: "1. Berat lembing dibedakan antara putra dan putri. 2. Lembing putri beratnya 600 gram. 3. Lembing putra lebih berat yaitu 800 gram." },
    { q: "Berat lembing untuk nomor putri adalah ....", options: ["600 gram", "800 gram", "400 gram", "500 gram"], answer: 0, solution: "1. Lembing putri dibuat lebih ringan dari lembing putra. 2. Lembing putra beratnya 800 gram. 3. Lembing putri ditetapkan 600 gram." },
    { q: "Lempar cakram dilakukan dari ....", options: ["Dalam lingkaran lempar", "Garis start", "Balok titian", "Atas papan tolakan"], answer: 0, solution: "1. Pelempar cakram melakukan putaran untuk mendapat momentum. 2. Putaran itu harus dilakukan di dalam lingkaran lempar. 3. Pelempar yang keluar lingkaran sebelum cakram mendarat dinyatakan gagal." },
    { q: "Berat cakram untuk nomor putra adalah ....", options: ["1 kg", "1,5 kg", "2 kg", "2,5 kg"], answer: 2, solution: "1. Berat cakram dibedakan antara putra dan putri. 2. Cakram putri beratnya 1 kilogram. 3. Cakram putra beratnya 2 kilogram." },
    { q: "Teknik mengumpan bola kepada teman satu tim dalam sepak bola disebut ....", options: ["Tackling", "Shooting", "Passing", "Dribbling"], answer: 2, solution: "1. Kerja sama tim dibangun lewat umpan yang akurat. 2. Mengumpan bola kepada teman disebut passing. 3. Passing yang baik memakai kaki bagian dalam agar arah terkontrol." },
    { q: "Menggiring bola melewati hadangan lawan sambil berlari disebut ....", options: ["Dribbling", "Heading", "Passing", "Shooting"], answer: 0, solution: "1. Menggiring bola adalah membawa bola dengan kaki. 2. Istilah untuk menggiring bola adalah dribbling. 3. Dribbling yang baik menjaga bola tetap dekat dengan kaki." },
    { q: "Tendangan keras yang diarahkan ke gawang lawan untuk mencetak gol disebut ....", options: ["Dribbling", "Shooting", "Stopping", "Passing"], answer: 1, solution: "1. Tujuan akhir serangan adalah mencetak gol. 2. Menendang bola ke arah gawang disebut shooting. 3. Shooting memakai punggung kaki agar tendangan keras dan terarah." },
    { q: "Teknik menghentikan laju bola agar mudah dikuasai disebut ....", options: ["Shooting", "Heading", "Stopping", "Tackling"], answer: 2, solution: "1. Bola umpan harus dikuasai sebelum diolah. 2. Menghentikan dan menguasai bola disebut stopping atau kontrol. 3. Stopping dapat memakai kaki, paha, atau dada." },
    { q: "Saat melakukan lemparan ke dalam (throw-in), posisi kaki pelempar harus ....", options: ["Berdiri dengan satu kaki", "Satu kaki terangkat ke depan", "Kedua kaki tetap menapak di tanah", "Melompat sebelum melempar"], answer: 2, solution: "1. Lemparan ke dalam memakai dua tangan dari belakang kepala. 2. Aturan juga mengatur posisi kaki pelempar. 3. Kedua kaki harus tetap menapak tanah dan tidak boleh terangkat." },
    { q: "Penjaga gawang (kiper) diperbolehkan menangkap bola dengan tangan ....", options: ["Di lingkaran tengah lapangan", "Di daerah pertahanan lawan", "Di seluruh area lapangan", "Hanya di dalam kotak penalti timnya sendiri"], answer: 3, solution: "1. Kiper adalah satu-satunya pemain yang boleh memegang bola. 2. Hak itu hanya berlaku di dalam kotak penalti timnya. 3. Kiper juga dilarang menangkap umpan balik yang disengaja dari teman satu tim." },
    { q: "Tugas utama pemain bertahan (bek) adalah ....", options: ["Menjaga daerah pertahanan dan menggagalkan serangan lawan", "Mengatur tempo permainan di lini tengah", "Menangkap bola dengan tangan", "Mencetak gol sebanyak mungkin"], answer: 0, solution: "1. Bek adalah benteng terakhir sebelum kiper. 2. Tugasnya menjaga daerah pertahanan. 3. Bek menggagalkan serangan lawan dengan intersep dan tekel bersih." },
    { q: "Pemain yang bertugas menghubungkan lini pertahanan dan lini penyerangan disebut ....", options: ["Kiper", "Bek", "Gelandang", "Striker"], answer: 2, solution: "1. Lini tengah adalah jembatan antar lini. 2. Pemain di posisi ini disebut gelandang atau midfielder. 3. Gelandang mengatur aliran bola dari bertahan ke menyerang." },
    { q: "Tugas utama penyerang (striker) adalah ....", options: ["Mengambil semua lemparan ke dalam", "Menjaga gawang dari kebobolan", "Menghalau bola di daerah pertahanan", "Mencetak gol ke gawang lawan"], answer: 3, solution: "1. Striker bermain paling dekat dengan gawang lawan. 2. Tugas utamanya mencetak gol. 3. Striker yang baik punya naluri mencari ruang tembak." },
    { q: "Kartu kuning yang diberikan wasit kepada pemain berarti ....", options: ["Hadiah untuk pemain terbaik", "Tanda pergantian pemain", "Pemain langsung diusir dari lapangan", "Peringatan atas pelanggaran yang dilakukan"], answer: 3, solution: "1. Wasit memberi kartu kuning untuk pelanggaran sedang. 2. Kartu kuning adalah peringatan resmi. 3. Pemain yang sudah dikartu kuning harus bermain lebih hati-hati." },
    { q: "Pemain yang menerima dua kartu kuning dalam satu pertandingan akan ....", options: ["Diusir dari lapangan seperti menerima kartu merah", "Dikenai denda uang tunai", "Tetap bermain seperti biasa", "Diistirahatkan selama 5 menit"], answer: 0, solution: "1. Dua kartu kuning setara dengan satu kartu merah. 2. Wasit akan mengusir pemain dari lapangan. 3. Timnya harus melanjutkan pertandingan dengan 10 pemain." },
    { q: "Tendangan sudut (corner kick) diberikan ketika bola keluar melewati garis gawang dan terakhir disentuh oleh ....", options: ["Pemain tim yang bertahan", "Pemain tim yang menyerang", "Wasit pertandingan", "Penonton di tribun"], answer: 0, solution: "1. Tendangan sudut diambil dari sudut lapangan. 2. Bola keluar lewat garis gawang memberi sepak pojok atau tendangan gawang. 3. Jika yang terakhir menyentuh adalah pemain bertahan, hadiahnya tendangan sudut untuk tim penyerang." },
    { q: "Tendangan gawang diberikan ketika bola keluar melewati garis gawang dan terakhir disentuh oleh ....", options: ["Penjaga gawang", "Pemain tim yang menyerang", "Pemain tim yang bertahan", "Wasit pertandingan"], answer: 1, solution: "1. Bola yang keluar lewat garis gawang bukan gol. 2. Jika terakhir disentuh pemain bertahan, lawan dapat tendangan sudut. 3. Jika terakhir disentuh pemain penyerang, tim bertahan mendapat tendangan gawang." },
    { q: "Pada tendangan bebas langsung, bola ....", options: ["Tidak boleh melewati pagar betis", "Hanya boleh ditendang oleh kiper", "Harus dioper dulu sebelum ditembak", "Boleh langsung ditendang masuk ke gawang lawan"], answer: 3, solution: "1. Tendangan bebas ada dua jenis: langsung dan tidak langsung. 2. Pada tendangan bebas langsung penendang boleh mencetak gol secara langsung. 3. Wasit menandakan jenisnya dengan posisi tangan saat pelanggaran." },
    { q: "Pada tendangan bebas tidak langsung, gol dinyatakan sah apabila ....", options: ["Bola menyentuh pemain lain terlebih dahulu sebelum masuk gawang", "Bola ditendang dari luar kotak penalti", "Bola sempat mengenai tiang gawang", "Bola langsung masuk tanpa menyentuh siapa pun"], answer: 0, solution: "1. Tendangan bebas tidak langsung tidak boleh langsung menjadi gol. 2. Bola harus menyentuh pemain lain dulu sebelum masuk. 3. Jika langsung masuk tanpa sentuhan, gol dianulir dan menjadi tendangan gawang." },
    { q: "Jumlah pergantian pemain yang diperbolehkan dalam pertandingan resmi adalah maksimal ....", options: ["3 kali", "5 kali", "7 kali", "Tidak dibatasi"], answer: 1, solution: "1. Pergantian pemain menjaga kebugaran tim. 2. Aturan modern memperbolehkan 5 kali pergantian. 3. Pergantian hanya boleh pada saat bola mati dan seizin wasit." },
    { q: "Wasit dalam pertandingan sepak bola dibantu oleh ....", options: ["Tidak dibantu siapa pun", "Satu hakim garis", "Dua asisten wasit (hakim garis)", "Empat wasit cadangan"], answer: 2, solution: "1. Wasit utama memimpin jalannya pertandingan. 2. Di sisi lapangan ada dua asisten wasit atau hakim garis. 3. Mereka membantu menilai offside dan bola keluar." },
    { q: "Sebuah gol dinyatakan sah apabila ....", options: ["Bola menyentuh tiang gawang", "Kiper sempat menyentuh bola", "Sebagian bola melewati garis gawang", "Seluruh bagian bola melewati garis gawang"], answer: 3, solution: "1. Gol adalah tujuan utama permainan. 2. Aturan menuntut seluruh bagian bola melewati garis gawang. 3. Bola yang masih menyentuh garis sedikit pun belum dianggap gol." },
    { q: "Waktu istirahat antara babak pertama dan babak kedua adalah ....", options: ["10 menit", "15 menit", "30 menit", "5 menit"], answer: 1, solution: "1. Pertandingan dibagi dua babak 45 menit. 2. Di antara kedua babak ada jeda istirahat. 3. Jeda istirahat ditetapkan maksimal 15 menit." },
    { q: "Tendangan untuk memulai pertandingan atau memulai babak kedua disebut ....", options: ["Tendangan penalti", "Tendangan sudut", "Tendangan bebas", "Kick-off"], answer: 3, solution: "1. Setiap babak diawali dengan tendangan mulai. 2. Tendangan ini dilakukan dari titik tengah lapangan. 3. Istilahnya adalah kick-off." },
    { q: "Tinggi net bola voli untuk pertandingan putri adalah ....", options: ["2,55 meter", "2,24 meter", "2,35 meter", "2,43 meter"], answer: 1, solution: "1. Tinggi net putra adalah 2,43 meter. 2. Net putri dibuat lebih rendah menyesuaikan jangkauan pemain. 3. Tinggi net putri ditetapkan 2,24 meter." },
    { q: "Servis bawah dalam bola voli dilakukan dengan cara ....", options: ["Bola dilempar melewati net", "Bola dipukul sambil melompat tinggi", "Bola dilambungkan lalu dipukul dengan telapak tangan dari atas", "Bola dipukul dari bawah dengan satu tangan yang terkepal"], answer: 3, solution: "1. Servis bawah adalah teknik servis paling dasar. 2. Bola dipegang satu tangan setinggi pinggang. 3. Tangan satunya yang terkepal mengayun dari bawah memukul bola." },
    { q: "Servis atas dalam bola voli dilakukan dengan cara ....", options: ["Bola dilambungkan lalu dipukul dengan telapak tangan di atas kepala", "Bola digulirkan melewati net", "Bola disundul melewati net", "Bola dipukul dari bawah dengan tangan terkepal"], answer: 0, solution: "1. Servis atas menghasilkan bola lebih keras dan terarah. 2. Bola dilambungkan dengan satu tangan. 3. Telapak tangan satunya memukul bola di atas kepala." },
    { q: "Passing bawah dalam bola voli menggunakan ....", options: ["Ujung jari-jari kedua tangan", "Kedua lengan bawah yang dirapatkan", "Telapak tangan yang terbuka", "Punggung tangan"], answer: 1, solution: "1. Passing bawah dipakai untuk menerima servis dan smash. 2. Kedua lengan bawah dirapatkan membentuk bidang datar. 3. Bola dipantulkan dengan lengan bawah, bukan ditangkap." },
    { q: "Passing atas dalam bola voli dilakukan dengan ....", options: ["Satu tangan yang terkepal", "Lengan bawah yang dirapatkan", "Jari-jari kedua tangan di depan dahi", "Telapak tangan sambil melompat"], answer: 2, solution: "1. Passing atas biasanya untuk mengumpan kepada smasher. 2. Bola didorong dengan jari-jari kedua tangan. 3. Posisi tangan berada di depan dahi dengan jari membentuk mangkuk." },
    { q: "Block (bendungan) dalam bola voli bertujuan untuk ....", options: ["Menerima servis lawan", "Mengumpan bola kepada smasher", "Memulai permainan", "Menahan smash lawan tepat di depan net"], answer: 3, solution: "1. Block dilakukan pemain baris depan dekat net. 2. Pemain melompat dengan kedua tangan terangkat. 3. Tujuannya menahan atau membendung smash lawan." },
    { q: "Saat terjadi perpindahan servis, rotasi pemain bola voli bergerak ....", options: ["Searah jarum jam", "Acak sesuai keinginan kapten", "Tidak boleh berpindah posisi", "Berlawanan arah jarum jam"], answer: 0, solution: "1. Tim yang merebut servis dari lawan wajib berotasi. 2. Setiap pemain bergeser satu posisi. 3. Arah pergeseran adalah searah jarum jam." },
    { q: "Satu set permainan bola voli dimenangkan oleh tim yang lebih dulu mencapai ....", options: ["15 poin", "21 poin", "25 poin dengan selisih 2 poin", "30 poin"], answer: 2, solution: "1. Bola voli memakai sistem rally point. 2. Setiap rally yang menang menghasilkan satu poin. 3. Satu set dimenangkan dengan 25 poin dan selisih minimal 2 poin." },
    { q: "Set penentuan (set kelima) dalam bola voli dimainkan sampai ....", options: ["25 poin", "11 poin", "15 poin", "21 poin"], answer: 2, solution: "1. Pertandingan voli memakai sistem terbaik dari 5 set. 2. Empat set awal dimainkan sampai 25 poin. 3. Set kelima sebagai penentu hanya sampai 15 poin dengan selisih 2 poin." },
    { q: "Libero dalam bola voli adalah ....", options: ["Pemain cadangan yang tidak boleh masuk", "Petugas pencatat skor", "Pemain yang khusus melakukan smash", "Pemain bertahan khusus dengan kaos berbeda warna"], answer: 3, solution: "1. Libero adalah spesialis pertahanan di baris belakang. 2. Ia mengenakan kaos berbeda warna agar mudah dikenali wasit. 3. Libero boleh keluar masuk menggantikan pemain belakang tanpa dihitung pergantian." },
    { q: "Pemain libero dilarang ....", options: ["Melakukan smash, block, dan servis", "Bermain di baris belakang", "Mengenakan kaos berbeda warna", "Menerima servis lawan"], answer: 0, solution: "1. Libero adalah pemain bertahan murni. 2. Ia tidak boleh menyerang ke daerah lawan. 3. Karena itu libero dilarang melakukan smash, block, dan servis." },
    { q: "Pemain yang bertugas mengumpan bola untuk dismash oleh teman disebut ....", options: ["Spiker", "Tosser (setter)", "Libero", "Server"], answer: 1, solution: "1. Serangan voli disusun lewat umpan yang tepat. 2. Pemain yang memberi umpan disebut tosser atau setter. 3. Umpan tosser yang baik memudahkan spiker melakukan smash." },
    { q: "Ukuran lapangan bola voli adalah ....", options: ["28 m x 15 m", "18 m x 9 m", "20 m x 10 m", "13,4 m x 6,1 m"], answer: 1, solution: "1. Lapangan voli berbentuk persegi panjang. 2. Net membaginya menjadi dua daerah sama besar. 3. Ukuran resminya adalah 18 meter x 9 meter." },
    { q: "Servis yang menyentuh net tetapi masuk ke daerah lawan dinyatakan ....", options: ["Harus diulang dari awal", "Pelanggaran net", "Fault dan poin untuk lawan", "Sah, permainan dilanjutkan"], answer: 3, solution: "1. Banyak yang mengira servis kena net otomatis gagal. 2. Aturan modern menyatakan servis seperti itu tetap sah. 3. Selama bola masuk daerah lawan, rally dilanjutkan." },
    { q: "Pemain yang menyentuh net saat bola sedang dimainkan dinyatakan ....", options: ["Melakukan pelanggaran", "Mendapat peringatan lisan", "Permainan tetap dilanjutkan", "Tidak apa-apa selama tidak disengaja"], answer: 0, solution: "1. Net tidak boleh diganggu saat rally berlangsung. 2. Sentuhan pada net oleh pemain adalah pelanggaran. 3. Poin diberikan kepada tim lawan." },
    { q: "Bola yang jatuh di luar garis lapangan berarti ....", options: ["Poin untuk tim yang memukul bola", "Poin untuk tim lawan", "Rally harus diulang", "Kedua tim mendapat poin"], answer: 1, solution: "1. Garis lapangan adalah batas daerah permainan. 2. Bola yang jatuh di luar garis berarti keluar. 3. Poin diberikan kepada tim lawan dari yang memukul." },
    { q: "Dalam satu tim bola voli, jumlah pemain yang menempati baris depan adalah ....", options: ["5 orang", "2 orang", "3 orang", "4 orang"], answer: 2, solution: "1. Enam pemain dibagi dua baris. 2. Baris depan bertugas menyerang dan memblock. 3. Jumlah pemain baris depan adalah 3 orang." },
    { q: "Sistem rally point dalam bola voli artinya ....", options: ["Poin dihitung setiap lima rally", "Hanya tim yang melakukan smash dapat poin", "Poin hanya didapat saat memegang servis", "Setiap rally yang dimenangkan menghasilkan poin"], answer: 3, solution: "1. Dulu poin hanya didapat tim yang memegang servis. 2. Sistem rally point mengubah aturan itu. 3. Kini setiap rally yang dimenangkan langsung menghasilkan satu poin." },
    { q: "Pertandingan bola voli memakai sistem terbaik dari 5 set, tim dinyatakan menang apabila memenangkan ....", options: ["3 set", "4 set", "5 set", "2 set"], answer: 0, solution: "1. Pertandingan maksimal 5 set. 2. Tim yang lebih dulu menang 3 set tidak terkejar lagi. 3. Karena itu pemenang ditentukan oleh 3 kemenangan set." },
    { q: "Satu regu bola voli terdiri atas ....", options: ["6 pemain tanpa cadangan", "8 pemain", "10 pemain", "12 pemain (6 pemain inti dan 6 cadangan)"], answer: 3, solution: "1. Di lapangan setiap tim menurunkan 6 pemain. 2. Regu juga membawa pemain cadangan. 3. Satu regu terdiri atas 12 pemain: 6 inti dan 6 cadangan." },
    { q: "Dribbling dalam bola basket adalah teknik ....", options: ["Menahan bola dengan dua tangan", "Menembak bola ke ring", "Memantulkan bola ke lantai sambil berjalan atau berlari", "Mengoper bola kepada teman"], answer: 2, solution: "1. Pemain yang membawa bola harus mendribble. 2. Dribbling adalah memantulkan bola ke lantai. 3. Bola dipantulkan dengan satu tangan sambil bergerak." },
    { q: "Chest pass adalah operan yang dilakukan ....", options: ["Dengan memantulkan bola ke lantai", "Sambil melompat tinggi", "Dengan satu tangan dari atas kepala", "Dengan dua tangan dari depan dada"], answer: 3, solution: "1. Chest berarti dada dalam bahasa Inggris. 2. Chest pass dilakukan dengan dua tangan dari depan dada. 3. Bola didorong lurus ke arah dada penerima." },
    { q: "Bounce pass adalah operan yang dilakukan dengan cara ....", options: ["Dipantulkan ke lantai terlebih dahulu", "Dilempar dari atas kepala", "Ditembakkan ke ring", "Dilempar lurus setinggi dada"], answer: 0, solution: "1. Bounce berarti memantul. 2. Bounce pass dipantulkan ke lantai sebelum sampai ke teman. 3. Teknik ini ampuh melewati hadangan tangan lawan." },
    { q: "Overhead pass dilakukan dengan ....", options: ["Dua tangan dari atas kepala", "Satu tangan dari samping badan", "Memantulkan bola ke lantai", "Dua tangan dari depan dada"], answer: 0, solution: "1. Overhead berarti dari atas kepala. 2. Overhead pass memakai dua tangan dari atas kepala. 3. Operan ini cocok untuk umpan jauh melewati lawan." },
    { q: "Jump shoot dalam bola basket adalah ....", options: ["Operan melambung ke teman", "Tembakan yang dilakukan sambil melompat", "Tembakan dari garis lemparan bebas", "Tembakan setelah dua langkah"], answer: 1, solution: "1. Jump berarti melompat. 2. Jump shoot adalah tembakan sambil melompat. 3. Lompatan membuat tembakan sulit diblock lawan." },
    { q: "Setiap lemparan bebas (free throw) yang masuk bernilai ....", options: ["3 poin", "4 poin", "1 poin", "2 poin"], answer: 2, solution: "1. Lemparan bebas adalah hadiah akibat pelanggaran. 2. Tembakan dilakukan tanpa dijaga dari garis bebas. 3. Setiap bola yang masuk bernilai 1 poin." },
    { q: "Tembakan dari luar garis busur tiga angka yang masuk bernilai ....", options: ["2 poin", "3 poin", "4 poin", "1 poin"], answer: 1, solution: "1. Nilai tembakan ditentukan posisi penembak. 2. Tembakan dari luar garis busur lebih sulit. 3. Karena itu tembakan yang masuk bernilai 3 poin." },
    { q: "Pivot dalam bola basket adalah gerakan ....", options: ["Melompat sambil menembak", "Berputar dengan satu kaki sebagai poros", "Berlari zig-zag menghindari lawan", "Merebut bola dari tangan lawan"], answer: 1, solution: "1. Pivot berarti berporos. 2. Satu kaki ditetapkan sebagai tumpuan poros. 3. Badan berputar pada kaki poros untuk mencari ruang operan atau tembakan." },
    { q: "Double dribble terjadi ketika pemain ....", options: ["Mendribble sambil melihat ke atas", "Mendribble dengan kecepatan tinggi", "Berhenti mendribble lalu mendribble lagi", "Mendribble dengan tangan kiri dan kanan bergantian"], answer: 2, solution: "1. Dribble yang berhenti tidak boleh dilanjutkan lagi. 2. Pemain yang memegang bola dengan dua tangan lalu mendribble lagi melanggar. 3. Pelanggaran ini disebut double dribble dan bola berpindah ke lawan." },
    { q: "Aturan 24 detik (shot clock) mewajibkan tim yang menguasai bola untuk ....", options: ["Beristirahat selama 24 detik", "Melakukan 24 kali pantulan bola", "Mengganti pemain setiap 24 detik", "Melakukan tembakan ke ring dalam waktu 24 detik"], answer: 3, solution: "1. Shot clock menjaga tempo permainan tetap cepat. 2. Tim harus menembak sebelum 24 detik habis. 3. Jika waktu habis tanpa tembakan, bola berpindah ke lawan." },
    { q: "Lama pertandingan bola basket menurut aturan FIBA adalah ....", options: ["4 x 8 menit", "4 x 10 menit", "2 x 45 menit", "2 x 20 menit"], answer: 1, solution: "1. Pertandingan basket dibagi menjadi kuarter. 2. Aturan FIBA menetapkan 4 kuarter. 3. Setiap kuarter berdurasi 10 menit sehingga total 4 x 10 menit." },
    { q: "Tinggi ring basket dari lantai adalah ....", options: ["2,75 meter", "3,05 meter", "3,25 meter", "3,50 meter"], answer: 1, solution: "1. Tinggi ring basket sudah distandarkan dunia. 2. Ukuran ini berlaku untuk semua level pertandingan. 3. Tinggi ring dari lantai adalah 3,05 meter." },
    { q: "Rebound dalam bola basket adalah ....", options: ["Pelanggaran memegang bola terlalu lama", "Operan yang dipantulkan ke lantai", "Usaha merebut bola yang memantul dari papan atau ring", "Tembakan dari luar garis tiga angka"], answer: 2, solution: "1. Tidak semua tembakan masuk ke ring. 2. Bola yang memantul dari papan atau ring diperebutkan. 3. Usaha merebut bola pantul itu disebut rebound." },
    { q: "Jump ball dilakukan pada ....", options: ["Setiap terjadi pelanggaran", "Saat bola keluar lapangan", "Akhir pertandingan", "Awal pertandingan untuk memperebutkan bola pertama"], answer: 3, solution: "1. Pertandingan harus diawali dengan perebutan bola yang adil. 2. Wasit melambungkan bola di lingkaran tengah. 3. Dua pemain melompat memperebutkannya, inilah jump ball." },
    { q: "Pemain yang melakukan 5 kali pelanggaran (foul) dalam satu pertandingan harus ....", options: ["Keluar dari pertandingan", "Istirahat selama 2 menit", "Pindah ke posisi lain", "Membayar denda kepada wasit"], answer: 0, solution: "1. Aturan FIBA membatasi jumlah foul pemain. 2. Pemain yang mencapai 5 foul dinyatakan fouled out. 3. Ia harus keluar dan digantikan pemain lain." },
    { q: "Pemain yang dilanggar saat menembak dan bola tetap masuk ke ring mendapatkan ....", options: ["2 kali lemparan bebas", "1 kali lemparan bebas tambahan", "Pengurangan poin tim lawan", "Tidak mendapatkan apa-apa"], answer: 1, solution: "1. Pelanggaran saat menembak tetap dihukum. 2. Karena bola masuk, poin tembakan tetap dihitung. 3. Pemain mendapat bonus 1 lemparan bebas tambahan." },
    { q: "Tembakan yang sama sekali tidak menyentuh ring atau papan disebut ....", options: ["Free throw", "Lay up", "Air ball", "Jump shoot"], answer: 2, solution: "1. Tembakan ideal menyentuh ring atau papan. 2. Tembakan yang hanya menyentuh udara gagal total. 3. Istilahnya adalah air ball." },
    { q: "Steal dalam bola basket adalah ....", options: ["Mengambil bola yang keluar lapangan", "Menyembunyikan bola dari wasit", "Merebut bola dari penguasaan lawan", "Mencuri waktu istirahat"], answer: 2, solution: "1. Pertahanan yang baik bisa merebut bola. 2. Merebut bola langsung dari tangan atau dribble lawan disebut steal. 3. Steal yang berhasil sering menjadi serangan balik cepat." },
    { q: "Posisi center biasanya diisi oleh pemain yang ....", options: ["Paling tinggi dan bermain di dekat ring", "Paling mahir mendribble", "Paling sedikit melakukan foul", "Larinya paling cepat"], answer: 0, solution: "1. Setiap posisi punya peran fisik berbeda. 2. Center bertugas di area dekat ring untuk rebound dan blok. 3. Karena itu center biasanya pemain tertinggi dalam tim." },
    { q: "Waktu istirahat antara kuarter kedua dan ketiga (half time) adalah ....", options: ["2 menit", "5 menit", "10 menit", "15 menit"], answer: 3, solution: "1. Pertandingan basket punya jeda antar kuarter. 2. Jeda antar kuarter biasa hanya 2 menit. 3. Jeda tengah pertandingan (half time) lebih lama yaitu 15 menit." },
    { q: "Servis pendek dalam bulu tangkis bertujuan menjatuhkan kok ....", options: ["Keluar dari lapangan", "Jauh ke garis belakang lawan", "Tipis di dekat net daerah lawan", "Setinggi kepala lawan"], answer: 2, solution: "1. Servis pendek umum dipakai pada nomor ganda. 2. Kok dipukul pelan agar jatuh tipis. 3. Targetnya adalah area tepat di depan net daerah lawan." },
    { q: "Servis panjang dalam bulu tangkis diarahkan ....", options: ["Mendatar setinggi net", "Tepat ke badan lawan", "Tipis di depan net", "Melambung jauh ke area belakang lapangan lawan"], answer: 3, solution: "1. Servis panjang umum dipakai pada nomor tunggal. 2. Kok dipukul tinggi dan jauh. 3. Targetnya adalah area belakang lapangan lawan." },
    { q: "Servis flick adalah servis yang ....", options: ["Selalu jatuh tepat di depan net", "Dipukul sekeras smash", "Dilakukan dari atas kepala", "Dilakukan dengan gerakan tipuan seperti servis pendek tetapi kok melambung jauh ke belakang"], answer: 3, solution: "1. Flick berarti sentilan tipuan. 2. Gerakan awalnya menyerupai servis pendek. 3. Namun kok disentil melambung jauh ke belakang lapangan lawan." },
    { q: "Pukulan lob (clear) dalam bulu tangkis adalah pukulan yang ....", options: ["Keras dan menukik tajam", "Melambung tinggi jauh ke belakang lapangan lawan", "Jatuh tipis di depan net", "Mendatar cepat setinggi net"], answer: 1, solution: "1. Lob dipakai untuk mengembalikan posisi bertahan. 2. Kok dipukul melambung tinggi. 3. Targetnya adalah garis belakang lapangan lawan." },
    { q: "Smash dalam bulu tangkis adalah pukulan ....", options: ["Tipis jatuh di depan net", "Halus dan melambung tinggi", "Keras dan menukik tajam ke daerah lawan", "Mendatar cepat setinggi net"], answer: 2, solution: "1. Smash adalah pukulan menyerang paling mematikan. 2. Kok dipukul keras dari atas. 3. Kok meluncur menukik tajam ke daerah lawan." },
    { q: "Pukulan drive dalam bulu tangkis adalah pukulan ....", options: ["Jatuh tipis di depan net", "Keras menukik dari atas", "Melambung tinggi ke belakang", "Mendatar dan cepat setinggi net"], answer: 3, solution: "1. Drive adalah pukulan serangan cepat. 2. Kok dipukul mendatar setinggi net. 3. Kecepatannya menyulitkan lawan bertahan." },
    { q: "Netting adalah pukulan yang ....", options: ["Tipis dan jatuh tepat di depan net daerah lawan", "Keras menembus pertahanan lawan", "Melambung melewati kepala lawan", "Dilakukan dari belakang lapangan"], answer: 0, solution: "1. Netting adalah pukulan halus di depan net. 2. Kok dipukul tipis agar melewati net. 3. Kok jatuh tepat di depan net daerah lawan." },
    { q: "Satu game bulu tangkis dimenangkan oleh pemain yang lebih dulu mencapai ....", options: ["11 poin", "15 poin", "21 poin dengan selisih 2 poin", "25 poin"], answer: 2, solution: "1. Bulu tangkis memakai sistem rally point. 2. Setiap rally menghasilkan satu poin. 3. Satu game dimenangkan dengan 21 poin dan selisih minimal 2 poin." },
    { q: "Apabila kedudukan 20-20 (deuce), permainan dilanjutkan sampai ....", options: ["Wasit menentukan pemenang", "Salah satu mencapai 21 poin", "Terjadi selisih 2 poin dengan batas maksimal 30 poin", "Dilakukan undian ulang"], answer: 2, solution: "1. Kedudukan 20-20 disebut deuce. 2. Pemenang harus unggul selisih 2 poin. 3. Jika mencapai 29-29, pemain yang meraih poin ke-30 menang." },
    { q: "Ukuran lapangan bulu tangkis adalah ....", options: ["23,77 m x 10,97 m", "28 m x 15 m", "13,40 m x 6,10 m", "18 m x 9 m"], answer: 2, solution: "1. Lapangan bulu tangkis berbentuk persegi panjang. 2. Net membaginya menjadi dua sisi sama. 3. Ukuran resminya adalah 13,40 meter x 6,10 meter." },
    { q: "Lebar lapangan bulu tangkis untuk nomor tunggal adalah ....", options: ["5,18 meter", "4,50 meter", "3,96 meter", "6,10 meter"], answer: 0, solution: "1. Garis samping ganda lebih lebar dari tunggal. 2. Pada nomor tunggal dipakai garis samping dalam. 3. Lebar lapangan tunggal adalah 5,18 meter." },
    { q: "Kok (shuttlecock) umumnya terbuat dari ....", options: ["Plastik padat", "Bulu angsa", "Karet mentah", "Kain tenun"], answer: 1, solution: "1. Kok harus ringan namun stabil di udara. 2. Kok standar memakai 16 helai bulu. 3. Bulu itu berasal dari sayap angsa." },
    { q: "Pukulan yang menyentuh net tetapi masuk ke daerah lawan dinyatakan ....", options: ["Poin untuk lawan", "Fault", "Sah dan permainan dilanjutkan", "Harus diulang"], answer: 2, solution: "1. Banyak pemain mengira pukulan kena net otomatis mati. 2. Aturan menyatakan pukulan tetap sah. 3. Selama kok masuk daerah lawan, rally dilanjutkan." },
    { q: "Pemain bulu tangkis dilarang ....", options: ["Melakukan servis pendek", "Bermain hingga tiga game", "Memukul kok di daerahnya sendiri", "Menyeberangkan raket melewati net saat memukul kok"], answer: 3, solution: "1. Setiap pemain hanya berhak atas daerahnya sendiri. 2. Raket tidak boleh menyeberangi net saat memukul. 3. Pelanggaran ini disebut fault dan poin untuk lawan." },
    { q: "Pertandingan bulu tangkis dimenangkan dengan sistem ....", options: ["Best of three, menang 2 dari 3 game", "Best of five", "Siapa cepat mencapai 50 poin", "Satu game penentuan"], answer: 0, solution: "1. Pertandingan terdiri atas beberapa game. 2. Sistem yang dipakai adalah best of three. 3. Pemain yang lebih dulu menang 2 game menjadi pemenang." },
{ q: "Ciri utama pegangan shakehand grip dalam tenis meja adalah ....", options: ["Tangan menggenggam gagang bet seperti berjabat tangan", "Ibu jari dan telunjuk menjepit gagang seperti memegang pena", "Seluruh jari melingkar pada kepala bet", "Gagang bet dijepit di antara jari tengah dan manis"], answer: 0, solution: "1. Shakehand artinya berjabat tangan dalam bahasa Inggris. 2. Tangan menggenggam gagang bet seperti orang berjabat tangan. 3. Pegangan seperti memegang pena disebut penhold grip, bukan shakehand." },
    { q: "Pegangan penhold grip lebih unggul dibanding shakehand grip pada pukulan ....", options: ["Backhand", "Block", "Forehand", "Chop"], answer: 2, solution: "1. Penhold memegang bet seperti pena sehingga sisi depan bet leluasa digerakkan. 2. Pergelangan tangan mudah diputar untuk memukul bola di sisi depan tubuh. 3. Karena itu penhold unggul pada pukulan forehand, sedangkan backhand-nya lebih terbatas." },
    { q: "Pukulan forehand dalam tenis meja dilakukan saat bola berada di ....", options: ["Sisi kiri tubuh pemain bertangan kanan", "Sisi kanan tubuh pemain bertangan kanan", "Tepat di atas kepala pemain", "Di belakang badan pemain"], answer: 1, solution: "1. Forehand memakai sisi telapak tangan untuk memukul bola. 2. Bagi pemain bertangan kanan, sisi telapak tangan menghadap ke sisi kanan tubuh. 3. Jadi pukulan forehand dilakukan saat bola berada di sisi kanan tubuh." },
    { q: "Ciri pukulan backhand dalam tenis meja adalah ....", options: ["Bola dipukul dengan telapak tangan menghadap ke depan", "Bet didorong lurus ke depan tanpa ayunan", "Bola dipukul dari bawah ke atas setinggi kepala", "Bola dipukul dengan punggung tangan menghadap ke depan"], answer: 3, solution: "1. Backhand adalah pukulan dengan sisi belakang tangan. 2. Saat memukul, punggung tangan menghadap ke arah datangnya bola. 3. Pukulan ini dipakai untuk bola di sisi kiri tubuh pemain bertangan kanan." },
    { q: "Pukulan push dalam tenis meja biasanya digunakan untuk ....", options: ["Mengembalikan bola rendah atau bola chop dengan dorongan pelan", "Menyerang dengan pukulan keras yang menukik tajam", "Memulai permainan dari belakang meja", "Menahan smash keras lawan di dekat net"], answer: 0, solution: "1. Push adalah pukulan dorongan dengan gerakan bet ke depan. 2. Pukulan ini cocok untuk bola yang rendah atau berputar bawah. 3. Push bukan pukulan menyerang karena lajunya pelan." },
    { q: "Teknik block dalam tenis meja bertujuan untuk ....", options: ["Memukul bola sekeras mungkin ke meja lawan", "Menahan bola smash lawan dengan bet yang hampir diam", "Memberi putaran bawah yang kuat pada bola", "Mengecoh lawan dengan servis yang sangat pendek"], answer: 1, solution: "1. Block dipakai saat menghadapi smash keras dari lawan. 2. Bet cukup dihadapkan ke arah datangnya bola tanpa ayunan besar. 3. Energi bola lawan dimanfaatkan sehingga bola kembali ke meja lawan." },
    { q: "Pukulan chop dalam tenis meja dilakukan dengan gerakan ....", options: ["Mendorong bet lurus ke depan", "Mengayun bet dari bawah ke atas dengan cepat", "Memotong dari atas ke bawah sehingga bola berputar ke bawah", "Menahan bet diam di depan badan"], answer: 2, solution: "1. Chop adalah pukulan bertahan dengan gerakan memotong. 2. Bet diayun dari atas ke bawah seperti gerakan memotong. 3. Hasilnya bola berputar ke bawah dan melambung rendah menyulitkan lawan." },
    { q: "Tinggi net tenis meja dari permukaan meja adalah ....", options: ["10,25 cm", "12,50 cm", "20,25 cm", "15,25 cm"], answer: 3, solution: "1. Net dipasang melintang tepat di tengah meja. 2. Ukuran net ditetapkan oleh federasi tenis meja dunia. 3. Tingginya adalah 15,25 cm dari permukaan meja." },
    { q: "Tinggi meja tenis meja dari lantai adalah ....", options: ["60 cm", "76 cm", "90 cm", "100 cm"], answer: 1, solution: "1. Ukuran meja tenis meja sudah berstandar internasional. 2. Selain panjang 2,74 m dan lebar 1,525 m, tingginya juga ditetapkan. 3. Tinggi meja dari lantai adalah 76 cm." },
    { q: "Dalam tenis meja, hak servis berpindah ke pemain lawan setiap ....", options: ["2 poin", "1 poin", "5 poin", "10 poin"], answer: 0, solution: "1. Aturan modern membatasi servis beruntun agar adil. 2. Setiap pemain melakukan servis dua kali berturut-turut. 3. Setelah dua poin, hak servis berpindah ke lawan." },
    { q: "Jika kedudukan 10-10 dalam tenis meja, servis bergantian setiap ....", options: ["2 poin", "3 poin", "1 poin", "5 poin"], answer: 2, solution: "1. Pada kedudukan 10-10 berlaku aturan deuce. 2. Permainan dilanjutkan sampai tercapai selisih dua poin. 3. Agar adil, servis bergantian setiap satu poin." },
    { q: "Pada permainan ganda tenis meja, servis harus dilakukan ....", options: ["Lurus ke depan menuju kotak mana pun", "Menyilang dari kotak kanan ke kotak kanan daerah lawan", "Menyilang dari kotak kiri ke kotak kanan daerah lawan", "Dari tengah meja menuju tengah meja lawan"], answer: 1, solution: "1. Meja untuk ganda dibagi garis tengah menjadi kotak kanan dan kiri. 2. Aturan mewajibkan servis menyilang secara diagonal. 3. Servis harus dari kotak servis kanan penyervis ke kotak kanan daerah lawan." },
    { q: "Servis yang menyentuh net lalu masuk ke meja lawan dinyatakan ....", options: ["Poin untuk penerima servis", "Poin untuk penyervis", "Pelanggaran dan servis hangus", "Let sehingga servis diulang"], answer: 3, solution: "1. Bola servis yang menyentuh net disebut let. 2. Let bukan poin bagi siapa pun. 3. Servis harus diulang tanpa mengurangi jatah servis pemain." },
    { q: "Bola tenis meja standar berdiameter ....", options: ["20 mm", "30 mm", "40 mm", "50 mm"], answer: 2, solution: "1. Ukuran bola tenis meja ditetapkan standar internasional. 2. Diameternya 40 mm dengan berat sekitar 2,7 gram. 3. Warnanya putih atau oranye agar mudah terlihat pemain." },
    { q: "Pertandingan tenis meja resmi umumnya dimenangkan pemain yang lebih dulu memenangkan ....", options: ["2 set dari 3 set", "3 set dari 5 set", "4 set dari 7 set", "5 set dari 9 set"], answer: 1, solution: "1. Pertandingan tenis meja memakai sistem best of. 2. Umumnya dimainkan dengan sistem best of 5 set. 3. Pemain yang lebih dulu memenangkan 3 set dinyatakan sebagai pemenang." },
    { q: "Jumlah pemain kasti dalam satu regu adalah ....", options: ["9 orang", "10 orang", "12 orang", "15 orang"], answer: 2, solution: "1. Kasti dimainkan oleh dua regu yang saling berhadapan. 2. Setiap regu terdiri atas 12 orang pemain. 3. Satu regu menjadi pemukul dan regu lain menjadi penjaga secara bergantian." },
    { q: "Lemparan bola kasti dari atas kepala dengan ayunan lengan ke depan disebut lemparan ....", options: ["Atas", "Bawah", "Samping", "Melambung"], answer: 0, solution: "1. Lemparan atas diawali bola diangkat ke belakang atas kepala. 2. Lengan diayun ke depan melewati atas kepala. 3. Lemparan ini cepat dan jauh sehingga cocok untuk mematikan pelari lawan." },
    { q: "Untuk mengoper bola jarak dekat kepada teman satu regu, lemparan yang tepat adalah lemparan ....", options: ["Atas", "Bawah", "Samping", "Melenting"], answer: 1, solution: "1. Lemparan bawah dilakukan dengan ayunan lengan dari bawah ke depan. 2. Bola meluncur pelan sehingga mudah ditangkap teman. 3. Karena itu lemparan bawah cocok untuk operan jarak dekat." },
    { q: "Cara menangkap bola lambung dalam permainan kasti adalah ....", options: ["Kedua tangan membentuk corong di depan dada atau dahi", "Satu tangan menengadah di samping badan", "Kedua tangan direndahkan di depan lutut", "Bola dibiarkan memantul ke tanah lebih dulu"], answer: 0, solution: "1. Bola lambung datang dari atas dengan arah menurun. 2. Kedua tangan direntangkan membentuk corong untuk memperluas bidang tangkapan. 3. Posisi tangan di depan dada atau dahi mengikuti arah datangnya bola." },
    { q: "Untuk menangkap bola yang menggelinding di tanah, posisi badan yang benar adalah ....", options: ["Berdiri tegak dengan tangan di atas kepala", "Berbaring lalu menggapai bola", "Melompat sambil menutup bola", "Jongkok dengan kedua tangan direndahkan di depan kaki"], answer: 3, solution: "1. Bola menggelinding bergerak rendah di permukaan tanah. 2. Badan direndahkan dengan jongkok agar tangan sejajar dengan bola. 3. Kedua tangan direndahkan di depan kaki siap menghadang laju bola." },
    { q: "Sikap awal yang benar saat akan memukul bola kasti adalah ....", options: ["Berdiri menghadap pelempar dengan satu tangan", "Berjongkok tepat di depan pelempar bola", "Berdiri menyamping dengan kedua tangan menggenggam pemukul", "Berdiri membelakangi pelempar bola"], answer: 2, solution: "1. Pemukul berdiri menyamping agar ayunan lengan leluasa. 2. Kedua tangan menggenggam ujung pemukul dengan kuat. 3. Pandangan mata fokus ke arah pelempar bola." },
    { q: "Fungsi tiang hinggap dalam permainan kasti adalah ....", options: ["Tempat persinggahan pemain pemukul setelah memukul bola", "Tempat pelempar bola berdiri melempar", "Tiang untuk mengikat jaring pengaman", "Tanda garis batas lapangan permainan"], answer: 0, solution: "1. Setelah memukul bola, pemain harus berlari mengelilingi lapangan. 2. Di tengah perjalanan terdapat tiang-tiang hinggap sebagai tempat singgah yang aman. 3. Pemain yang tidak singgah di tiang hinggap dapat dimatikan oleh regu lawan." },
    { q: "Pemain lawan dapat dimatikan dengan cara ....", options: ["Berteriak agar pemain lawan berhenti berlari", "Melempar bola hingga mengenai badannya saat berlari", "Menarik baju pemain lawan yang sedang berlari", "Menghalangi jalan lari pemain lawan"], answer: 1, solution: "1. Regu penjaga berusaha mematikan pemain regu pemukul. 2. Caranya adalah melempar bola hingga mengenai badan pelari yang sedang berlari. 3. Pelari yang terkena lemparan dinyatakan mati." },
    { q: "Bola hasil pukulan yang ditangkap langsung regu penjaga sebelum menyentuh tanah mengakibatkan ....", options: ["Pemukul mendapat nilai tambahan", "Permainan diulang dari awal", "Regu penjaga mendapat hukuman", "Pemukul dinyatakan mati"], answer: 3, solution: "1. Bola pukulan yang melambung dapat ditangkap regu penjaga. 2. Jika tertangkap langsung sebelum menyentuh tanah, pukulan dianggap gagal. 3. Pemukul yang bolanya tertangkap dinyatakan mati." },
    { q: "Pemukul yang gagal memukul bola dalam tiga kali kesempatan dinyatakan ....", options: ["Mendapat tambahan dua kali pukulan", "Boleh memukul sambil berlari", "Mati dan gilirannya hangus", "Menjadi pelempar bola"], answer: 2, solution: "1. Setiap pemukul diberi kesempatan untuk memukul bola. 2. Batas kesempatan memukul adalah tiga kali percobaan. 3. Jika tiga kali gagal memukul, pemukul dinyatakan mati." },
    { q: "Regu pemukul memperoleh nilai apabila pemainnya ....", options: ["Berhasil kembali ke ruang bebas dengan selamat setelah berlari", "Memukul bola sejauh mungkin tanpa berlari", "Berdiri diam di tiang hinggap sampai permainan selesai", "Menangkap bola lemparan dari regu penjaga"], answer: 0, solution: "1. Tujuan regu pemukul adalah mengumpulkan nilai sebanyak-banyaknya. 2. Nilai didapat dengan berlari melewati tiang-tiang hinggap. 3. Pemain yang kembali ke ruang bebas dengan selamat menyumbang nilai bagi regunya." },
    { q: "Tugas utama regu penjaga dalam permainan kasti adalah ....", options: ["Memukul bola sejauh mungkin", "Menangkap bola dan mematikan pemain lawan", "Berlari mengelilingi tiang hinggap", "Menghitung nilai regu pemukul"], answer: 1, solution: "1. Dua regu dalam kasti memiliki tugas yang berlawanan. 2. Regu pemukul bertugas memukul bola dan berlari mencari nilai. 3. Regu penjaga bertugas menangkap bola hasil pukulan dan mematikan pemain lawan." },
    { q: "Regu pemukul dan regu penjaga bertukar tempat apabila ....", options: ["Regu pemukul berhasil mendapat satu nilai", "Waktu permainan mencapai lima menit", "Salah satu pemain meminta pergantian", "Seluruh pemain regu pemukul sudah selesai atau dimatikan"], answer: 3, solution: "1. Permainan kasti dimainkan dengan bergiliran memukul dan menjaga. 2. Giliran memukul berakhir bila semua pemain sudah mendapat giliran atau dimatikan lawan. 3. Setelah itu kedua regu bertukar peran." },
    { q: "Alat pemukul dalam permainan kasti terbuat dari ....", options: ["Kayu berbentuk bulat memanjang", "Besi berbentuk pipih", "Plastik berbentuk kotak", "Bambu berbentuk lembaran"], answer: 0, solution: "1. Pemukul kasti harus ringan tetapi kuat. 2. Bahan yang dipakai adalah kayu. 3. Bentuknya bulat memanjang dengan bagian pegangan di ujungnya." },
    { q: "Ruang bebas dalam permainan kasti adalah ....", options: ["Daerah terlarang yang tidak boleh dimasuki pemain", "Tempat duduk penonton pertandingan", "Tempat berkumpul pemain pemukul sebelum memukul dan setelah kembali berlari", "Garis batas akhir lapangan permainan"], answer: 2, solution: "1. Setiap permainan kasti memiliki ruang bebas sebagai markas regu pemukul. 2. Pemain menunggu giliran memukul di ruang bebas. 3. Pemain yang selesai berlari dengan selamat juga kembali ke ruang bebas." },
    { q: "Sikap akhir yang benar setelah melakukan guling depan adalah ....", options: ["Jongkok dengan kedua tangan lurus ke depan", "Berdiri tegak dengan tangan di samping badan", "Telentang dengan kedua kaki ditekuk", "Duduk dengan kedua kaki diluruskan"], answer: 0, solution: "1. Guling depan diakhiri setelah badan selesai berputar penuh. 2. Posisi akhir kembali jongkok seperti posisi awal. 3. Kedua tangan diluruskan ke depan untuk menjaga keseimbangan." },
    { q: "Bagian tubuh yang pertama menyentuh matras saat melakukan guling depan adalah ....", options: ["Dahi", "Punggung", "Tengkuk", "Bahu"], answer: 2, solution: "1. Saat berguling, dagu ditempelkan ke dada. 2. Kepala menekuk sehingga tengkuk lebih dulu menyentuh matras. 3. Dahi yang menyentuh matras justru berbahaya dan berarti tekniknya salah." },
    { q: "Fungsi kedua tangan saat melakukan guling belakang adalah ....", options: ["Menarik lutut agar rapat ke dada", "Menolak matras di samping telinga agar kepala tidak terbentur", "Menahan pinggang supaya tidak jatuh", "Melambai untuk menjaga keseimbangan"], answer: 1, solution: "1. Pada guling belakang, badan berputar ke belakang melewati kepala. 2. Kedua tangan diletakkan di samping telinga dengan telapak menempel matras. 3. Tangan menolak matras untuk membantu putaran sekaligus melindungi kepala." },
    { q: "Sikap awal guling depan yang benar adalah ....", options: ["Berdiri membelakangi matras dengan tangan di pinggang", "Telentang dengan kedua kaki lurus", "Duduk dengan kaki menyilang", "Jongkok menghadap matras dengan kedua tangan menumpu di depan kaki"], answer: 3, solution: "1. Guling depan bergerak ke arah depan. 2. Awalan dilakukan dengan jongkok menghadap matras. 3. Kedua tangan menumpu matras di depan kaki selebar bahu." },
    { q: "Gerakan sikap lilin diawali dari posisi ....", options: ["Tidur telentang dengan kedua kaki rapat", "Berdiri tegak menghadap matras", "Jongkok membelakangi matras", "Duduk dengan kaki diluruskan"], answer: 0, solution: "1. Sikap lilin adalah mengangkat kedua kaki lurus ke atas. 2. Gerakan diawali dengan tidur telentang di atas matras. 3. Kedua kaki rapat lalu diangkat perlahan hingga lurus ke atas menyerupai lilin." },
    { q: "Gerakan headstand bertumpu pada ....", options: ["Kedua siku dan lutut", "Punggung dan kedua kaki", "Dahi atau ubun-ubun kepala dan kedua tangan", "Dada dan perut"], answer: 2, solution: "1. Headstand adalah sikap berdiri terbalik dengan kepala sebagai tumpuan. 2. Selain kepala bagian dahi atau ubun-ubun, kedua tangan ikut menumpu. 3. Bertumpu hanya pada kepala tanpa tangan sangat berbahaya bagi leher." },
    { q: "Pada gerakan headstand, kepala dan kedua tangan membentuk ....", options: ["Garis lurus", "Segitiga sama sisi", "Lingkaran", "Segi empat"], answer: 1, solution: "1. Keseimbangan headstand bergantung pada titik-titik tumpuan. 2. Kepala diletakkan di depan dan kedua tangan di samping sedikit ke belakang. 3. Ketiga titik tumpu tersebut membentuk segitiga sama sisi yang kokoh." },
    { q: "Awalan gerakan handstand yang benar adalah ....", options: ["Duduk bersila lalu melompat ke atas", "Tidur telentang lalu mengangkat kaki", "Berlari kencang lalu melompat", "Berdiri, langkahkan satu kaki ke depan, lalu kedua tangan menumpu matras"], answer: 3, solution: "1. Handstand diawali dari posisi berdiri tegak. 2. Salah satu kaki dilangkahkan ke depan sebagai awalan. 3. Badan dibungkukkan hingga kedua tangan menumpu matras, lalu kaki diayun ke atas." },
    { q: "Untuk melakukan kayang dari posisi tidur telentang, kedua tangan diletakkan ....", options: ["Di samping telinga dengan telapak tangan menempel matras", "Di samping pinggang dengan kepalan tangan", "Di atas perut dengan jari-jari merapat", "Di bawah kepala sebagai bantal"], answer: 0, solution: "1. Kayang dari tidur diawali telentang dengan lutut ditekuk. 2. Kedua tangan ditekuk ke samping telinga. 3. Telapak tangan menempel matras siap menolak badan ke atas." },
    { q: "Gerakan kayang dari posisi berdiri dilakukan dengan cara ....", options: ["Badan dibungkukkan ke depan hingga tangan menyentuh kaki", "Badan diputar ke samping seperti roda", "Kedua tangan diangkat ke atas lalu badan dilengkungkan ke belakang", "Langsung menjatuhkan badan ke belakang"], answer: 2, solution: "1. Kayang dari berdiri membutuhkan kelenturan punggung yang baik. 2. Kedua tangan diangkat lurus ke atas. 3. Badan dilengkungkan perlahan ke belakang hingga kedua tangan menyentuh matras." },
    { q: "Gerakan meroda dalam senam lantai disebut juga ....", options: ["Handspring", "Cartwheel", "Somersault", "Flic-flac"], answer: 1, solution: "1. Meroda adalah gerakan memutar badan ke arah samping. 2. Istilah dalam bahasa Inggris untuk gerakan ini adalah cartwheel. 3. Handspring dan somersault adalah gerakan salto yang berbeda tekniknya." },
    { q: "Pada gerakan meroda, badan berputar ke arah ....", options: ["Depan seperti guling depan", "Belakang seperti guling belakang", "Atas seperti melompat", "Samping menyerupai roda yang berputar"], answer: 3, solution: "1. Meroda diawali dengan berdiri menyamping arah gerakan. 2. Tangan dan kaki menumpu bergantian di matras. 3. Badan berputar ke samping menyerupai roda yang berputar, sesuai dengan namanya." },
    { q: "Urutan tumpuan yang benar pada gerakan meroda adalah ....", options: ["Tangan dan kaki bergantian satu per satu", "Kedua tangan bersamaan lalu kedua kaki bersamaan", "Kedua kaki dulu baru kedua tangan", "Hanya kedua tangan tanpa tumpuan kaki"], answer: 0, solution: "1. Meroda memakai tumpuan tangan dan kaki secara bergantian. 2. Diawali satu tangan, lalu tangan satunya, disusul kaki bergantian. 3. Tumpuan kedua tangan bersamaan justru menjadi gerakan handspring, bukan meroda." },
    { q: "Gerakan lompat harimau diawali dengan ....", options: ["Berdiri diam lalu berguling ke depan", "Jongkok lalu melompat di tempat", "Lari beberapa langkah lalu menolak dengan kedua kaki", "Berjalan pelan tanpa awalan"], answer: 2, solution: "1. Lompat harimau adalah lompatan menyerupai harimau menerkam mangsa. 2. Gerakan diawali lari beberapa langkah untuk mendapat kecepatan. 3. Tolakan dilakukan dengan kedua kaki secara bersamaan." },
    { q: "Perbedaan utama lompat harimau dengan guling depan adalah ....", options: ["Lompat harimau dilakukan tanpa menggunakan tangan", "Lompat harimau memiliki fase melayang di udara sebelum mendarat", "Guling depan diawali dengan lari kencang", "Guling depan mendarat dengan satu kaki"], answer: 1, solution: "1. Kedua gerakan sama-sama bergerak ke arah depan. 2. Guling depan langsung berguling di matras tanpa fase melayang. 3. Lompat harimau melompat jauh ke depan sehingga ada fase melayang di udara." },
    { q: "Senam lantai sebaiknya dilakukan di atas ....", options: ["Lantai keramik yang licin", "Tanah yang berbatu", "Papan kayu yang keras", "Matras yang empuk dan tidak licin"], answer: 3, solution: "1. Senam lantai banyak melibatkan putaran dan tumpuan badan. 2. Alas yang empuk meredam benturan jika pesenam jatuh. 3. Permukaan yang tidak licin menjaga pesenam tidak terpeleset." },
    { q: "Sikap kapal terbang dilakukan dengan cara ....", options: ["Berdiri dengan satu kaki, kaki lain lurus ke belakang, kedua tangan direntangkan", "Berdiri dengan kedua kaki rapat dan tangan di pinggang", "Duduk dengan kedua kaki lurus ke depan", "Tidur telentang dengan kedua tangan menyilang"], answer: 0, solution: "1. Sikap kapal terbang menyerupai pesawat terbang. 2. Tumpuan hanya pada satu kaki dengan badan condong ke depan. 3. Kaki yang lain lurus ke belakang dan kedua tangan direntangkan seperti sayap." },
    { q: "Agar aman saat berlatih senam lantai, pesenam sebaiknya ....", options: ["Berlatih sendirian tanpa pengawasan", "Langsung mencoba gerakan sulit tanpa pemanasan", "Dibantu teman sebagai pengaman di sampingnya", "Berlatih di permukaan yang licin"], answer: 2, solution: "1. Gerakan senam berisiko membuat pesenam jatuh dan cedera. 2. Teman sebagai pengaman siap menahan jika pesenam kehilangan keseimbangan. 3. Berlatih sendirian berbahaya karena tidak ada yang menolong saat cedera." },
    { q: "Sikap akhir guling belakang yang benar adalah ....", options: ["Berdiri dengan satu kaki diangkat", "Jongkok dengan kedua tangan lurus ke depan", "Telentang dengan tangan di atas kepala", "Duduk bersila menghadap ke belakang"], answer: 1, solution: "1. Guling belakang diakhiri setelah putaran badan selesai. 2. Badan kembali ke posisi jongkok. 3. Kedua tangan diluruskan ke depan untuk menjaga keseimbangan." },
    { q: "Rangkaian gerakan senam lantai secara umum melatih ....", options: ["Kecepatan lari jarak jauh", "Daya tahan berenang", "Ketepatan menembak bola", "Kelenturan, kekuatan, dan keseimbangan tubuh"], answer: 3, solution: "1. Senam lantai berisi gerakan mengguling, bertumpu, dan melompat. 2. Gerakan tersebut membutuhkan otot yang kuat dan lentur. 3. Banyak sikap bertumpu yang sekaligus melatih keseimbangan tubuh." },
    { q: "Kekuatan sebagai komponen kebugaran jasmani adalah ....", options: ["Kemampuan otot untuk melawan beban atau tahanan", "Kemampuan bergerak secepat mungkin", "Kemampuan sendi bergerak seluas-luasnya", "Kemampuan mengubah arah dengan cepat"], answer: 0, solution: "1. Kekuatan berkaitan dengan kerja otot tubuh. 2. Otot yang kuat mampu mengangkat, mendorong, atau menahan beban berat. 3. Contohnya kemampuan menahan berat badan saat push up." },
    { q: "Daya tahan otot adalah kemampuan otot untuk ....", options: ["Mengangkat beban maksimal dalam sekali angkat", "Bergerak secepat kilat dalam sekejap", "Meregang sejauh mungkin", "Bekerja dalam waktu lama tanpa cepat lelah"], answer: 3, solution: "1. Daya tahan otot berbeda dengan kekuatan maksimal. 2. Daya tahan diukur dari lamanya otot bekerja berulang-ulang. 3. Contohnya melakukan sit up berkali-kali dalam 30 detik." },
    { q: "Kecepatan sebagai komponen kebugaran jasmani adalah kemampuan ....", options: ["Bertahan lama saat berolahraga", "Bergerak atau berpindah tempat dalam waktu sesingkat-singkatnya", "Menjaga tubuh tetap seimbang", "Mengubah arah tanpa kehilangan keseimbangan"], answer: 1, solution: "1. Kecepatan mengutamakan waktu tempuh yang singkat. 2. Contohnya lari 50 meter dengan waktu tercepat. 3. Komponen ini berbeda dengan daya tahan yang mengutamakan durasi lama." },
    { q: "Kelincahan adalah kemampuan tubuh untuk ....", options: ["Berlari jauh tanpa berhenti", "Mengangkat beban yang sangat berat", "Mengubah arah dengan cepat dan tepat tanpa kehilangan keseimbangan", "Melakukan gerakan lambat dan terkontrol"], answer: 2, solution: "1. Kelincahan dibutuhkan dalam olahraga permainan seperti sepak bola. 2. Pemain harus berbelok atau berbalik arah dengan cepat. 3. Perubahan arah harus tetap tepat dan seimbang agar tidak jatuh." },
    { q: "Keseimbangan adalah kemampuan untuk ....", options: ["Mempertahankan posisi tubuh saat diam maupun bergerak", "Berlari secepat mungkin", "Melompat setinggi mungkin", "Melempar sejauh mungkin"], answer: 0, solution: "1. Keseimbangan menjaga tubuh agar tidak jatuh. 2. Dibutuhkan baik saat berdiri diam maupun saat bergerak. 3. Contohnya berdiri dengan satu kaki atau berjalan di balok titian." },
    { q: "Koordinasi sebagai komponen kebugaran jasmani adalah kemampuan ....", options: ["Menggerakkan satu anggota tubuh sekuat tenaga", "Menahan napas selama mungkin", "Berdiri diam tanpa bergerak", "Menggabungkan beberapa gerakan tubuh menjadi satu rangkaian yang selaras"], answer: 3, solution: "1. Banyak gerakan olahraga melibatkan beberapa anggota tubuh sekaligus. 2. Koordinasi menyelaraskan gerak tangan, kaki, dan mata. 3. Contohnya memukul bola kasti sambil memperhatikan arah datangnya bola." },
    { q: "Daya ledak atau power adalah gabungan dari komponen ....", options: ["Kelenturan dan keseimbangan", "Kekuatan dan kecepatan", "Daya tahan dan kelincahan", "Koordinasi dan ketepatan"], answer: 1, solution: "1. Daya ledak disebut juga power dalam istilah olahraga. 2. Power adalah kemampuan mengerahkan tenaga maksimal dalam waktu singkat. 3. Tenaga maksimal berasal dari kekuatan, sedangkan waktu singkat berasal dari kecepatan." },
    { q: "Tes sit up selama 30 detik bertujuan mengukur ....", options: ["Daya tahan otot perut", "Kekuatan otot lengan", "Kelenturan pinggang", "Kecepatan reaksi"], answer: 0, solution: "1. Sit up adalah gerakan bangun dari posisi telentang berulang-ulang. 2. Otot yang bekerja utama adalah otot perut. 3. Jumlah ulangan dalam 30 detik menunjukkan daya tahan otot perut." },
    { q: "Tes back up bertujuan mengukur ....", options: ["Kelenturan otot kaki", "Daya tahan jantung dan paru-paru", "Kekuatan dan daya tahan otot punggung", "Kecepatan lari"], answer: 2, solution: "1. Back up adalah gerakan mengangkat badan dari posisi tengkurap. 2. Otot yang bekerja utama adalah otot punggung. 3. Tes ini mengukur kekuatan dan daya tahan otot punggung." },
    { q: "Tes shuttle run 4 x 10 meter bertujuan mengukur ....", options: ["Kecepatan maksimal", "Kelincahan", "Daya tahan jantung", "Kekuatan kaki"], answer: 1, solution: "1. Shuttle run adalah lari bolak-balik 10 meter sebanyak 4 kali. 2. Pelari harus berbalik arah dengan cepat di setiap ujung lintasan. 3. Kemampuan berbalik arah dengan cepat adalah kelincahan." },
    { q: "Tes vertical jump atau lompat tegak bertujuan mengukur ....", options: ["Kelenturan sendi lutut", "Keseimbangan tubuh", "Daya tahan otot lengan", "Daya ledak otot tungkai"], answer: 3, solution: "1. Vertical jump adalah lompatan tegak setinggi-tingginya. 2. Lompatan membutuhkan tenaga kaki yang besar dalam sekejap. 3. Tenaga besar dalam waktu singkat adalah daya ledak otot tungkai." },
    { q: "Tes lari 50 meter bertujuan mengukur komponen ....", options: ["Kecepatan", "Daya tahan jantung", "Kelincahan", "Keseimbangan"], answer: 0, solution: "1. Lari 50 meter ditempuh dengan kecepatan penuh. 2. Waktu tempuh yang singkat menunjukkan kecepatan yang baik. 3. Jaraknya terlalu pendek untuk mengukur daya tahan jantung." },
    { q: "Tes berdiri dengan satu kaki seperti burung bangau bertujuan mengukur ....", options: ["Kekuatan", "Kecepatan", "Keseimbangan", "Daya ledak"], answer: 2, solution: "1. Tes ini dikenal dengan nama stork stand. 2. Peserta berdiri dengan satu kaki selama mungkin tanpa jatuh. 3. Lamanya bertahan menunjukkan kemampuan keseimbangan tubuh." },
    { q: "Komponen kebugaran yang paling dominan dibutuhkan pelari maraton adalah ....", options: ["Kecepatan reaksi", "Daya tahan jantung dan paru-paru", "Daya ledak otot lengan", "Kelenturan sendi bahu"], answer: 1, solution: "1. Maraton menempuh jarak lebih dari 42 kilometer. 2. Pelari harus menjaga pasokan oksigen selama berjam-jam. 3. Kemampuan memasok oksigen lama adalah daya tahan jantung dan paru-paru." },
    { q: "Denyut nadi saat berlatih yang baik berada pada kisaran ....", options: ["60 sampai 80 persen dari denyut nadi maksimal", "20 sampai 40 persen dari denyut nadi maksimal", "90 sampai 100 persen dari denyut nadi maksimal", "Sama persis dengan denyut nadi maksimal"], answer: 0, solution: "1. Latihan terlalu ringan tidak meningkatkan kebugaran. 2. Latihan mendekati maksimal berbahaya bagi jantung. 3. Kisaran yang aman dan efektif adalah 60 sampai 80 persen denyut nadi maksimal." },
    { q: "Cara praktis mengukur denyut nadi saat berolahraga adalah ....", options: ["Menebak dari rasa lelah yang dirasakan", "Menghitung selama 1 detik lalu dikali 100", "Menunggu sampai napas kembali normal", "Meraba pergelangan tangan lalu menghitung denyut selama 15 detik dikali 4"], answer: 3, solution: "1. Denyut nadi teraba di pergelangan tangan atau leher. 2. Menghitung penuh 60 detik membuang waktu latihan. 3. Menghitung 15 detik lalu dikali 4 memberi hasil per menit yang cukup akurat." },
    { q: "Tujuan utama melakukan pendinginan setelah berolahraga adalah ....", options: ["Langsung menghentikan semua aktivitas tubuh", "Menambah massa otot dengan cepat", "Mengembalikan kondisi tubuh ke normal secara bertahap", "Menaikkan suhu tubuh setinggi mungkin"], answer: 2, solution: "1. Setelah latihan berat, jantung berdenyut cepat dan otot menegang. 2. Berhenti mendadak bisa menyebabkan pusing atau pingsan. 3. Pendinginan berupa gerakan ringan menurunkan kerja tubuh secara perlahan." },
    { q: "Urutan latihan kebugaran yang benar adalah ....", options: ["Pemanasan, latihan inti, pendinginan", "Latihan inti, pemanasan, pendinginan", "Pendinginan, pemanasan, latihan inti", "Pemanasan, pendinginan, latihan inti"], answer: 0, solution: "1. Tubuh perlu disiapkan sebelum melakukan kerja berat. 2. Pemanasan di awal menyiapkan otot dan jantung. 3. Setelah latihan inti, pendinginan menutup rangkaian latihan dengan aman." },
    { q: "Frekuensi latihan kebugaran yang dianjurkan dalam seminggu adalah ....", options: ["1 kali", "3 sampai 5 kali", "Setiap jam", "10 kali"], answer: 1, solution: "1. Latihan terlalu jarang tidak meningkatkan kebugaran. 2. Latihan tanpa jeda istirahat membuat tubuh kelelahan. 3. Anjuran yang umum adalah 3 sampai 5 kali seminggu dengan hari istirahat di antaranya." },
    { q: "Agar kebugaran terus meningkat, beban latihan harus ....", options: ["Langsung dinaikkan ke tingkat maksimal", "Diturunkan setiap minggu", "Sama terus tanpa perubahan", "Dinaikkan secara bertahap sesuai kemampuan"], answer: 3, solution: "1. Tubuh beradaptasi dengan beban latihan yang diberikan. 2. Beban yang sama terus membuat perkembangan berhenti. 3. Kenaikan bertahap memberi tantangan yang aman bagi tubuh." },
    { q: "Latihan lari zig-zag melewati beberapa tiang bertujuan melatih ....", options: ["Kekuatan otot perut", "Daya tahan jantung", "Kelincahan", "Kelenturan bahu"], answer: 2, solution: "1. Lari zig-zag menuntut pelari berbelok-belok dengan cepat. 2. Setiap belokan adalah perubahan arah gerak. 3. Kemampuan mengubah arah dengan cepat adalah kelincahan." },
    { q: "Latihan lompat tali atau skipping secara rutin melatih ....", options: ["Daya tahan jantung dan paru-paru serta koordinasi", "Kekuatan otot leher", "Kelenturan jari tangan", "Kecepatan menulis"], answer: 0, solution: "1. Lompat tali dilakukan berulang dalam waktu yang cukup lama. 2. Jantung dan paru-paru bekerja memasok oksigen selama latihan. 3. Tangan memutar tali selaras dengan lompatan kaki sehingga koordinasi ikut terlatih." },
    { q: "Push up bagi peserta yang belum kuat biasanya dimodifikasi dengan ....", options: ["Tangan diletakkan di belakang punggung", "Lutut sebagai tumpuan pengganti ujung kaki", "Badan ditopang tali dari atas", "Gerakan dilakukan sambil berlari"], answer: 1, solution: "1. Push up penuh menahan seluruh berat badan. 2. Menekuk lutut sebagai tumpuan memperpendek tuas beban tubuh. 3. Beban pada lengan berkurang sehingga gerakan menjadi lebih ringan." },
    { q: "Daya tahan jantung dan paru-paru disebut juga daya tahan ....", options: ["Anaerobik sesaat", "Otot statis", "Sendi pasif", "Aerobik atau kardiovaskular"], answer: 3, solution: "1. Jantung dan paru-paru bertugas memasok oksigen ke otot. 2. Kerja tubuh dengan oksigen disebut kerja aerobik. 3. Karena melibatkan jantung dan pembuluh darah, disebut juga kardiovaskular." },
    { q: "Setelah berolahraga berat sebaiknya tidak langsung duduk diam karena ....", options: ["Otot langsung menjadi besar", "Tubuh menjadi terlalu dingin", "Darah dapat menumpuk di kaki dan menimbulkan pusing", "Nafsu makan langsung hilang"], answer: 2, solution: "1. Saat berolahraga, darah dipompa kuat ke seluruh tubuh. 2. Berhenti mendadak membuat darah menumpuk di bagian kaki. 3. Akibatnya kepala kekurangan darah dan timbul pusing, maka perlu pendinginan dulu." },
    { q: "Tujuan utama memberikan pertolongan pertama pada kecelakaan adalah ....", options: ["Mencegah kondisi korban bertambah parah sebelum bantuan medis tiba", "Menyembuhkan semua cedera sampai tuntas", "Menggantikan peran dokter sepenuhnya", "Memindahkan korban sejauh mungkin"], answer: 0, solution: "1. P3K adalah pertolongan sementara, bukan pengobatan tuntas. 2. Tindakan cepat mencegah pendarahan atau cedera bertambah buruk. 3. Setelah diberi P3K, korban tetap perlu dibawa ke tenaga medis." },
    { q: "Huruf I dalam prinsip penanganan cedera RICE adalah ....", options: ["Injection yaitu menyuntik obat", "Ice yaitu mengompres cedera dengan es", "Immobilization dengan gips", "Inspection dengan rontgen"], answer: 1, solution: "1. RICE adalah singkatan dari Rest, Ice, Compression, Elevation. 2. Huruf I berarti Ice atau es. 3. Cedera dikompres dengan es yang dibungkus kain untuk mengurangi bengkak." },
    { q: "Mengompres cedera terkilir dengan es bertujuan ....", options: ["Menghangatkan otot yang kaku", "Mempercepat pendarahan", "Mengurangi bengkak dan rasa nyeri", "Melemaskan sendi yang kaku"], answer: 2, solution: "1. Es membuat pembuluh darah di sekitar cedera menyempit. 2. Penyempitan mengurangi aliran darah ke daerah cedera. 3. Akibatnya bengkak berkurang dan rasa nyeri mereda." },
    { q: "Pada 24 sampai 48 jam pertama setelah cedera memar atau terkilir, kompres yang tepat adalah ....", options: ["Kompres air panas", "Kompres minyak panas", "Tanpa kompres sama sekali", "Kompres dingin atau es"], answer: 3, solution: "1. Cedera yang baru masih mengalami pendarahan kecil di dalam jaringan. 2. Kompres dingin menyempitkan pembuluh darah. 3. Kompres panas justru memperlebar pembuluh dan memperparah bengkak." },
    { q: "Penanganan yang tepat saat betis kram ketika berolahraga adalah ....", options: ["Berhenti, luruskan kaki, dan regangkan otot betis perlahan", "Terus berlari agar kram hilang sendiri", "Memijat dengan tekanan sangat keras", "Menyiram betis dengan air panas mendidih"], answer: 0, solution: "1. Kram adalah kontraksi otot mendadak yang menyakitkan. 2. Aktivitas harus dihentikan agar otot beristirahat. 3. Peregangan perlahan membantu otot kembali rileks." },
    { q: "Kram otot saat berolahraga umumnya disebabkan oleh ....", options: ["Terlalu banyak minum air putih", "Kelelahan otot, kurang pemanasan, dan kekurangan cairan", "Udara yang terlalu sejuk", "Pakaian yang terlalu longgar"], answer: 1, solution: "1. Otot yang lelah mudah mengalami kontraksi tak terkendali. 2. Tanpa pemanasan, otot kaget menerima beban berat. 3. Kekurangan cairan mengganggu kerja otot sehingga kram mudah terjadi." },
    { q: "Luka memar akibat terbentur benda keras tanpa luka terbuka ditangani dengan ....", options: ["Menyayat memar agar darah keluar", "Mengoleskan balsem panas tebal-tebal", "Mengompres dingin dan mengistirahatkan bagian yang memar", "Menusuk memar dengan jarum"], answer: 2, solution: "1. Memar adalah pecahnya pembuluh darah kecil di bawah kulit. 2. Tidak ada luka terbuka sehingga tidak perlu dibersihkan seperti luka lecet. 3. Kompres dingin mengurangi bengkak dan rasa nyeri." },
    { q: "Jika luka mengeluarkan banyak darah, tindakan pertama yang harus dilakukan adalah ....", options: ["Membiarkan darah mengalir sampai berhenti sendiri", "Menaburi luka dengan kopi bubuk", "Mengikat erat di atas luka sampai membiru", "Menekan luka dengan kain bersih untuk menghentikan pendarahan"], answer: 3, solution: "1. Pendarahan banyak berbahaya karena korban bisa kehabisan darah. 2. Tekanan langsung pada luka membantu pembuluh darah menutup. 3. Kain bersih mencegah kuman masuk ke dalam luka." },
    { q: "Korban yang diduga mengalami patah tulang sebaiknya ....", options: ["Tidak digerakkan, dipasang bidai, lalu dibawa ke rumah sakit", "Dipijat agar tulangnya kembali lurus", "Disuruh berjalan untuk melatih tulang", "Dibiarkan tanpa penanganan apa pun"], answer: 0, solution: "1. Menggerakkan tulang yang patah dapat merobek otot dan pembuluh darah. 2. Bidai menahan agar bagian yang patah tidak bergeser. 3. Penanganan lanjutan harus dilakukan tenaga medis di rumah sakit." },
    { q: "Tanda-tanda tulang patah adalah ....", options: ["Kulit menjadi lebih halus", "Bentuk tidak normal, nyeri hebat, dan tidak bisa digerakkan", "Tubuh terasa lebih ringan", "Nafsu makan bertambah"], answer: 1, solution: "1. Tulang yang patah kehilangan bentuk aslinya. 2. Rasa nyeri hebat muncul saat bagian itu disentuh atau digerakkan. 3. Bagian yang patah sulit atau tidak bisa digerakkan secara normal." },
    { q: "Dislokasi adalah cedera berupa ....", options: ["Patahnya tulang menjadi dua bagian", "Robeknya kulit hingga berdarah", "Bergesernya ujung tulang dari kedudukan sendinya", "Putusnya pembuluh darah besar"], answer: 2, solution: "1. Dislokasi terjadi pada persendian seperti bahu atau jari. 2. Ujung tulang keluar dari mangkuk sendinya. 3. Tulang yang bergeser tidak boleh dipaksa kembali sendiri dan harus ditangani tenaga medis." },
    { q: "Pemain yang terbentur kepala lalu merasa pusing dan mual harus ....", options: ["Dipaksa lanjut bermain agar terbiasa", "Diberi minum bersoda lalu main lagi", "Disuruh tidur di pinggir lapangan sendirian", "Dihentikan bermain dan segera diperiksa tenaga medis"], answer: 3, solution: "1. Benturan kepala berisiko menyebabkan gegar otak. 2. Pusing dan mual adalah tanda bahaya pada otak. 3. Pemain harus istirahat dan diperiksa dokter sebelum boleh bermain lagi." },
    { q: "Cara mencegah dehidrasi saat berolahraga adalah ....", options: ["Minum air sebelum, selama, dan setelah berolahraga", "Tidak minum sama sekali agar tidak kembung", "Minum hanya setelah selesai lomba", "Mengganti air dengan minuman bersoda"], answer: 0, solution: "1. Tubuh kehilangan banyak cairan melalui keringat. 2. Cairan perlu diganti sebelum tubuh kekurangan. 3. Minum sebelum, selama, dan setelah olahraga menjaga tubuh tetap terhidrasi." },
    { q: "Pertolongan pertama pada korban heat stroke adalah ....", options: ["Menjemur korban di bawah terik matahari", "Memindahkan ke tempat teduh, mengompres, dan memberi minum bila sadar", "Memberi selimut tebal agar berkeringat", "Menyuruh korban terus berlari"], answer: 1, solution: "1. Heat stroke adalah kondisi tubuh kepanasan secara berlebihan. 2. Korban harus dijauhkan dari sumber panas ke tempat teduh. 3. Kompres dan minum membantu menurunkan suhu tubuh, tetapi korban tak sadar jangan diberi minum." },
    { q: "Berikut ini yang termasuk isi kotak P3K adalah ....", options: ["Obat tidur, pisau lipat, dan korek api", "Permen, mainan, dan majalah", "Kasa steril, plester, perban elastis, gunting, dan antiseptik", "Baterai, kabel, dan obeng"], answer: 2, solution: "1. Kotak P3K berisi peralatan pertolongan darurat. 2. Kasa steril dan plester untuk menutup luka. 3. Perban elastis untuk membebat, gunting untuk memotong, dan antiseptik untuk membersihkan luka." },
    { q: "Berikut ini yang BUKAN termasuk isi kotak P3K adalah ....", options: ["Kasa steril", "Plester luka", "Pinset", "Pisau dapur yang tajam"], answer: 3, solution: "1. Isi kotak P3K adalah peralatan medis darurat. 2. Kasa steril, plester luka, dan pinset termasuk peralatan medis. 3. Pisau dapur bukan alat medis dan berbahaya sehingga tidak termasuk." },
    { q: "Korban jatuh yang diduga mengalami cedera tulang belakang sebaiknya ....", options: ["Tidak dipindahkan dan menunggu tenaga medis datang", "Langsung didudukkan paksa", "Disuruh berdiri dan berjalan", "Digotong beramai-ramai ke tempat jauh"], answer: 0, solution: "1. Tulang belakang melindungi saraf tulang belakang. 2. Memindahkan korban bisa menggeser tulang dan melukai saraf. 3. Cedera saraf tulang belakang bisa menyebabkan kelumpuhan sehingga korban jangan dipindah." },
    { q: "Nyeri di perut samping saat berlari atau suduken dapat diatasi dengan ....", options: ["Berlari semakin kencang", "Memperlambat lari dan mengatur pernapasan", "Menahan napas selama mungkin", "Berhenti total lalu duduk membungkuk lama"], answer: 1, solution: "1. Suduken adalah kram otot di sekitar rusuk akibat pernapasan tak teratur. 2. Memperlambat lari mengurangi beban otot pernapasan. 3. Pernapasan yang teratur membantu kram mereda." },
    { q: "Saat menolong luka yang berdarah, penolong sebaiknya memakai ....", options: ["Tangan kosong agar lebih cepat", "Kain kotor yang ada di sekitar", "Sarung tangan karet agar tidak tertular penyakit lewat darah", "Plastik bekas bungkus makanan"], answer: 2, solution: "1. Darah korban bisa membawa kuman penyakit. 2. Sarung tangan menjadi penghalang antara darah dan kulit penolong. 3. Ini melindungi penolong sekaligus menjaga luka tetap bersih." },
    { q: "Pertolongan pertama pada teman yang pingsan di lapangan adalah ....", options: ["Menyiram wajah dengan air es banyak-banyak", "Mendudukkan lalu mengguncang badannya", "Memberi makan agar cepat sadar", "Membaringkan, melonggarkan pakaian, dan meninggikan kaki sedikit"], answer: 3, solution: "1. Pingsan terjadi karena otak kekurangan darah sesaat. 2. Berbaring dengan kaki sedikit ditinggikan membantu darah mengalir ke otak. 3. Pakaian dilonggarkan agar napas lega, dan korban yang tak kunjung sadar dibawa ke UKS atau rumah sakit." }
  ]
};
